SELECT 'moj-all-verified-judgments-review-002-chunk-007' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6d1c2ecf-addc-5da8-a2b4-a406d549530f","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -تصادم سيارتني -مطالبة بأرش تلفيات سيارة - تقدير أرش تلفيات سيارة من قبل أهل اخلبرة -حكم بشاهد ومين -إلزام املدعى عليه بدفع أرش تلفيات سيارة املدعي -إقرار باستالم املبلغ احملكوم به .","document_number":"3418933","case_number":"33611693","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة باملصادقة على احلكم -حضر املدعي وقرر استالمه للمبلغ احملكوم به","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"حادث مروري -تصادم سيارتني -مطالبة بأرش تلفيات سيارة - تقدير أرش تلفيات سيارة من قبل أهل اخلبرة -حكم بشاهد ومين -إلزام املدعى عليه بدفع أرش تلفيات سيارة املدعي -إقرار باستالم املبلغ احملكوم به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/21 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3418933 :‬‬\n                        ‫َر ْق ُم الدعوى‪33611693 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34203062‬تاريخه‪1434/5/1 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬تصــادم ســيارتني ‪ -‬مطالبــة بــأرش تلفيــات ســيارة ‪-‬‬\n     ‫تقديــر أرش تلفيــات ســيارة مــن قبــل أهــل اخلبــرة ‪ -‬حكــم بشــاهد وميــن‬\n     ‫‪ -‬إلــزام املدعــى عليــه بدفــع أرش تلفيــات ســيارة املدعــي ‪ -‬إقــرار باســتالم‬\n                                                                ‫املبلــغ احملكــوم بــه ‪.‬‬\n\n\n\n                            ‫قضاء النبي صلى اهلل عليه وسلم بالشاهد واليمني‬\n\n\n\n\n     ‫ادعــى املدعــي بــأن املدعــى عليــه تســبب يف تلفيــات حلقــت بســيارة‬\n     ‫املدعــي جــراء حــادث مــروري وأديــن املدعــى عليــه بنســبة اخلطــأ ‪%100‬‬\n     ‫وطالــب باحلكــم علــى املدعــى عليــه بــأرش تلفيــات الســيارة ‪ -‬أجــاب‬\n     ‫املدعــى عليــه بــأن املتســبب يف احلــادث هــو املدعــي وطالــب بــأرش تلفيات‬\n     ‫ســيارته ‪ -‬أحضــر املدعــي شــاهد ًا واحــد ًا تضمنــت شــهادته صحــة دعوى‬\n     ‫املدعــي و ُعـ ِّـدلَ الشــاهد ‪ -‬قــرر املدعــى عليــه أن شــهادة الشــاهد غيــر‬\n     ‫صحيحــة وان الشــاهد ال يعلــم عنــه شــيئ ًا ‪ -‬افهــم ناظــر القضيــة املدعــي‬\n     ‫بــأن عليــه بــذل اليمــن علــى صحــة دعــواه وحلــف علــى ذلــك ‪ -‬مت تقديــر‬\n     ‫أرش تلفيــات ســيارة املدعــي مــن قبــل أهــل اخلبــرة صــدر احلكــم بإلــزام‬\n     ‫املدعــى عليــه بتســليم األرش للمدعــي ‪ -‬قــرر املدعــي القناعــة وقــرر‬\n\n‫‪15‬‬\n\f‫املدعــى عليــه عــدم القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة‬\n‫املكرمــة باملصادقــة علــى احلكــم ‪ -‬حضــر املدعــي وقــرر اســتالمه‬\n                                                 ‫للمبلــغ احملكــوم بــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا مســاعد رئيــس احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 33611693‬وتاريــخ‬\n‫‪1433/10/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331843913‬وتاريــخ‬\n‫‪ 1433/10/18‬هـ ففي ي ـ ــوم الثالثاء املوافق‪1433/11/09‬هـ افتتحت‬\n‫اجللســة الــساعـ ـ ــة ‪ 10: 15‬وفيهــا حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .....‬وأدعــى علــى احلاضــر معــه ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم قائــا يف دعــواه عليــه تســبب املدعــى عليــه‬\n‫يف تلفيــات حلقــت بســيارتي جــراء حــادث مــروري أديــن فيــه بنســبة مائــة‬\n‫باملائــة أطلــب احلكــم عليــه بــأرش تلفيــات ســيارتي هــذه دعواي وبســؤال‬\n‫املدعــى عليــه قــال مــا ادعــاه املدعــي غيــر صحيــح والصحيــح أن املدعــي‬\n‫هــو املتســبب يف احلــادث وأطلبــه أرش تلفيــات ســيارتي فســألت املدعــي‬\n‫وصــف احلــادث فقــال أن املدعــى عليــه جتــاوز بســيارته اجليــب ســيارتي‬\n‫الكامــري مــن اليمــن وتفاجــأ بصاحــب حافلــة يف وجهــه فانحــرف‬\n‫بســيارته علــى ســيارتي فأتلــف االســطب األمامــي األميــن وشــيئا مــن‬\n‫الصــدام والكبــوت والشــمعة وبعــرض ذلــك علــى املدعــى عليــه قــال ال‬\n‫صحــة ملــا ادعــاه املدعــي فســألت املدعــي البينــة فقــال أطلــب امهالــي‬\n‫ويف يــوم اإلثنــن املوافــق‪ 1433/12/27‬ه ـ افتتحــت اجللســة الســاعة (‬\n\n                                                                                 ‫‪16‬‬\n\f     ‫‪ ) 9 : 00‬وفيهــا حضــر الطرفــان وجــرى ســؤال املدعــى عليــه عــن وصــف‬\n     ‫احلــادث فقــال كنــت أســير يف شــارع ‪........‬بعــد قاعــة ‪........‬وكنــت‬\n     ‫أســير يف املســار األيســر وتفاجــأت باملدعــي يقــود ســيارته الكامــري‬\n     ‫بعــد اخلــط األصفــر وصدمنــي مــن اجلهــة اليســرى وتزحلقــت ســيارتي‬\n     ‫مــن قــوة االصطــدام وصدمــت يف الصبــات وانكســر الكفــر األمامــي‬\n     ‫وتدحــرج حتــى دخــل يف الشــارع الثانــي فطلبــت مــن املدعــي البينــة‬\n     ‫فأحضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم مــن مواليــد‬\n     ‫عــام ‪1401‬ه ـ ويســكن مكــة فســألته عــن عالقتــه باملدعــي فقــال ال‬\n     ‫تربطنــي بــه عالقــة ســوى رابطــة الديــن وباستشــهاده شــهد هلل قائــا‬\n     ‫كنــت أســير يف طريقــي وجتاوزنــي ســيارتني الكامــري يف املقدمــة‬\n     ‫واجليــب خلفــه مباشــرة وكانــا يســيران بســرعة جنونيــة وعنــد وصولــي‬\n     ‫إلــى املنعطــف رأيــت كلتــا الســيارتني اجليــب يف اليمــن والكامــري يف‬\n     ‫اليســار قــد وقــع بينهمــا حــادث اصطــدام ولــم أرهمــا حلظــة االصطــدام‬\n     ‫فنزلــت وســألت املدعــى عليــه صاحــب اجليــب كيــف وقــع احلــادث فقــال‬\n     ‫كنــت خلــف صاحــب الكامــري ويقصــد املدعــي وحاولــت جتــاوزه‬\n     ‫باالنحــراف مــن جهــة اليمــن إال أننــي تفاجــأت بصاحــب احلافلــة يف‬\n     ‫وجهــي فاضطــررت إلــى االنحــراف علــى الكامــري حتــى ال اصطــدم‬\n     ‫باحلافلــة وانحرفــت جهــة اليســار وصدمــت الكامــري ثــم انحرفــت جهــة‬\n     ‫احلافلــة وصدمتهــا هــذا مــا لــدي مــن شــهادة وبعــرض حــال الشــاهد ومــا‬\n     ‫جــاء يف شــهادته علــى املدعــى عليــه قــال أمــا حالــه فــا أعلــم عنــه شــيئا‬\n     ‫وأمــا مــا جــاء يف شــهادته فشــهادته غيــر صحيحــة فســألت املدعــي هــل‬\n     ‫لديــك زيــادة بينــة فقــال ليــس لــدي ســوى مــن أحضــرت فطلبــت مــن‬\n     ‫املدعــى عليــه البينــة علــى مــا ادعــاه مــن وصــف احلــادث فقــال ليــس لــدي‬\n\n\n‫‪17‬‬\n\f‫بينــة فطلبــت م ـ ــن املدعــي تزكي ــة شــاهـ ــده فاستعـ ـ ــد بذلــك ويف ي ـ ـ ـ ــوم‬\n‫اإلثنني املواف ـ ــق‪1434/01/12‬هـ افتتحت اجللـ ـ ـس ــة الساعـ ـ ــة ( ‪) 9 : 30‬‬\n‫وفيهــا حضــر الطرفــان وأحضــر املدعــي معــه ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم و ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫وباستشــهادهما شــهدا بعدالــة وثقــة الشــاهد املذكــور أعــاه عليــه‬\n‫أفهمــت املدعــي بــأن عليــه بــذل اليمــن بــأن املدعــى عليــه انحــرف‬\n‫بســيارته جهــة اجلانــب األميــن مــن ســيارته وأن املدعــى عليــه هــو مــن‬\n‫صدمــه يف اجلانــب األميــن مــن ســيارته وأن وصــف املدعــى عليــه للحــادث‬\n‫غيــر صحيــح فحلــف قائــا واهلل العظيــم أن املدعــى عليــه انحــرف‬\n‫بســيارته علــى ســيارتي مــن اجلانــب األميــن واصطــدم بهــا وأن وصــف‬\n‫املدعــى عليــه للحــادث غيــر صحيــح فجــرى االطــاع علــى تقديــر شــيخ‬\n‫املعــارض املرفــق باملعاملــة لفــه (‪ )19‬وجــاء فيــه تقديــر ســيارة املدعــي‬\n‫قبــل احلــادث ( ‪ )26000‬وبعــده (‪ )24200‬وبنــاء علــى مــا تقــدم وشــهادة‬\n‫الشــاهد وميــن املدعــي وحيــث ال بينــة للمدعــى عليــه علــى دعــواه‬\n‫ولقضــاء النبــي صلــى اهلل عليــه وســلم بالشــاهد واليمــن فقــد حكمــت‬\n‫علــى املدعــى عليــه بدفــع ألــف وثمامنائــة ريــال (‪ )1800‬للمدعــي وبعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــي قناعتــه باحلكــم كمــا قــرر املدعــى‬\n‫عليــه االعتــراض وطلــب محكمــة االســتئناف فأجبتــه لطلبــه وأفهمتــه‬\n‫بــأن مــدة االعتــراض ثالثــون يومــا تبــدأ مــن يــوم الســبت ‪1434/1/17‬ه ـ‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪ 1434/01/12‬ه ـ‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/04/16‬ه ـ افتتحت اجللســة الســاعة (‪30‬‬\n‫‪ )10 :‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n\n\n                                                                                            ‫‪18‬‬\n\f     ‫بالرقــم ‪ 34525469‬يف ‪1434/3/11‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة‬\n     ‫األولــى رقــم ‪ 3456552‬يف ‪1434/3/7‬ه ـ املتضمــن ودراســة احلكــم‬\n     ‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا إعادتهــا لفضيلــة حاكــم‬\n     ‫القضيــة ملالحظــة أن الشــاهد ذكــر يف شــهادته أن املدعــي واملدعــى‬\n     ‫عليــه كانــا يســيران بســرعة جنونيــة وهــذا يعنــي أنهمــا يتحمــان ســويا‬\n     ‫مســؤولية احلــادث كمــا أن مــن أعــد تقريــر احلــادث ذكــر يف تقريــره‬\n     ‫أن نســبة اخلطــأ علــى الطرفــن بنســبة خمســن باملائــة علــى كل واحــد‬\n     ‫منهمــا فعلــى فضيلتــه إعــادة النظــر والتأمــل وعــرض الصلــح علــى‬\n     ‫الطرفــن وإجــراء مــا يلــزم واهلل املوفــق واجلــواب عليــه ذكــر أصحــاب‬\n     ‫الفضيلــة أن معــد تقريــر احلــادث ذكــر يف تقريــره أن نســبة اخلطــأ علــى‬\n     ‫الطرفــن بنســبة خمســن باملائــة علــى كل واحــد منهمــا والصحيــح‬\n     ‫أن محضــر نســبة اإلدانــة املرفــق باملعاملــة لفــه (‪ )31‬قــد وضــع النســبة‬\n     ‫كاملــة علــى املدعــى عليــه أمــا مــا ذكــره الشــاهد وهــوا أنهمــا كانــا‬\n     ‫يســيران بســرعة جنونيــة فهــذا حــن جتــاوزه املتداعيــان بســيارتهما ثــم‬\n     ‫غابــا عنــه ثــم لــو فــرض أن املدعــي كان يســير بســرعة فليســت الســرعة‬\n     ‫ســببا يف احلــادث وإمنــا الســبب هــوا انحــراف املدعــى عليــه اخلاطــئ ولــذا‬\n     ‫فلــم يظهــر لــي مــا يوجــب إعــادة النظــر فيمــا حكمــت بــه وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                 ‫‪ 1434/04/16‬هــ‪.‬‬\n     ‫ويف يــوم الثالثــاء املوافــق‪ 1435/01/23‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫(‪ )10 : 00‬وفيهــا حضــر املدعــي وقــرر اســتالمه كامــل املبلــغ احملكــوم‬\n     ‫بــه لــذا جــرى إثبــات ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1435/01/23‬ه ـ‬\n\n\n‫‪19‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34833377‬وتاريــخ‬\n‫‪ 1434/4/22‬هـ ـ املرفــق بهــا الصــك الشــرعي رقــم ‪ 3418933‬وتاريــخ‬\n‫‪ 1434/1/21‬هـ ـ الصــادر مــن فضيلــة الشــيخ ‪ /‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى ضــد ‪ /‬املتهــم بقضيــة‬\n                            ‫حــادث مــروري احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪20‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":15,"source_page_end":20,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ed77fd932c8f66d894d207b858cf4d431455b51ecc799191d28faeb1f4e58151","normalized_text_hash":"f72b299c90fdbb7adc959d39be5373bcd4c5ffe90f61b5c0c69608b6f7551a87","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p15-3418933"},{"id":"ec7a4672-6155-59c9-9810-bdbcfcbe92c8","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -أخذ سيارة بدون علم صاحبها والصدم بها -تقدير قيمة تلفيات السيارة -إثبات اإلدانة باإلقرار -اإللزام بدفع قيمة","document_number":"3422357","case_number":"3429721","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة عيون اجلواء املنتدب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/25","year":"1434","subject":"حادث مروري -أخذ سيارة بدون علم صاحبها والصدم بها -تقدير قيمة تلفيات السيارة -إثبات اإلدانة باإلقرار -اإللزام بدفع قيمة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/1/25 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3422357 :‬‬\n                        ‫َر ْق ُم الدعوى‪3429721 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪34183747‬تاريخه‪1434/4/9 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬أخــذ ســيارة بــدون علــم صاحبهــا والصــدم بهــا ‪ -‬تقديــر‬\n     ‫قيمــة تلفيــات الســيارة ‪ -‬إثبــات اإلدانــة باإلقــرار‪ -‬اإللــزام بدفــع قيمــة‬\n                                                                       ‫األرش األقــل‪.‬‬\n\n\n\n\n                                                               ‫‪ -1‬قاعدة ‪:‬ال عذر ملن أقر ‪.‬‬\n                                                     ‫‪ -2‬قاعدة ‪ :‬اإلقرار حجه على املقر ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بأخــذ مفتــاح ســيارته مــن دون‬\n     ‫علمــه أثنــاء تواجدهمــا يف اســتراحة ‪ -‬انقلــب املدعــى عليــه بالســيارة يف‬\n     ‫الطريــق العــام ‪ -‬مت تقديــر أرش التلفيــات مــن قبــل معرضــن للســيارات‬\n     ‫‪ -‬طلــب املدعــي إلــزام املدعــى عليــه بدفــع األرش ‪ -‬أقــر املدعــى عليــه‬\n     ‫مبــا جــاء يف دعــوى املدعــي ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n     ‫األرش األقــل ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪21‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة العامــة مبحافظــة‬\n‫عيــون اجلــواء املنتــدب وبنــاء على املعاملــة املقيدة لدينا برقم ‪34143796‬‬\n‫وتاريــخ ‪1434/1/18‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/01/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــى علــى احلاضــر معــه ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬قائــا يف دعــواه عليــه لقــد قــام‬\n‫املدعــى عليــه بأخــذ مفتــاح ســيارتي نــوع ‪ ....‬لوحــة رقــم (‪ )...‬دون علمــي‬\n‫حيــث كنــت أنــا وإيــاه يف اســتراحة يف منطقــة حائــل وقــام بالذهــاب‬\n‫بالســيارة إلــى جهــة ال أعلمهــا وأخبرنــي أحــد زمالئــي أن ســيارتي‬\n‫املذكــورة أعــاه منقلبــة قريبــا مــن االســتراحة علــى شــارع عــام وذهبــت‬\n‫إلــى ســيارتي ووجــدت املــرور عندهــا وأنــا ال أعــرف مــن قــام بهــذا العمــل‬\n‫حينهــا ثــم ســألت رجــل املــرور أيــن قائــد الســيارة فقــال لــي يف مستشــفى‬\n‫امللــك خالــد يف حائــل وعندمــا ذهبــت وجــدت أنــه زميلــي املدعــى عليــه‬\n‫وكمــا أســلفت فقــد أخــذ املفتــاح دون علمــي حيــث إننــي وضعــت‬\n‫املفتــاح حتــت الفــراش يف االســتراحة وقــد قــدرت الســيارة قبــل وبعــد‬\n‫احلــادث مــن معــرض ‪ ...‬مبوجــب اخلطــاب املرفــق باملعاملــة لفــة رقــم (‪)8‬‬\n‫قبــل احلــادث مبلــغ وقــدره ســتون ألــف ريــال وبعــد احلــادث مببلــغ وقــدره‬\n‫خمســة عشــر ألــف ريــال ليصبــح الفــارق بــن القيمتــن مبلــغ وقــدره‬\n‫خمســة وأربعــون ألــف ريــال كمــا قــدرت مــن معــرض ‪ ...‬للســيارات‬\n‫حســب اللفــة رقــم (‪ )7‬املرفقــة باملعاملــة قبــل احلــادث مببلــغ وقــدره ســتون‬\n‫ألــف ريــال وبعــد احلــادث مببلــغ وقــدره خمســة عشــر ألــف ريــال والفــرق‬\n\n                                                                                      ‫‪22‬‬\n\f     ‫بــن القيمتــن هــو مبلــغ وقــدره خمســة وأربعــون ألــف ريــال لذلــك كلــه‬\n     ‫أطلــب إلــزام املدعــى عليــه بتســليمي الفــرق بــن القيمتــن وهــو مبلــغ‬\n     ‫وقــدره خمســة وأربعــون ألــف ريــال حــا ًال هــذه دعــواي وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي يف دعــواه كلــه صحيــح‬\n     ‫جملــة وتفصيــا وقــد أخــذت الســيارة دون علــم املدعــي مــن ابــن عمــه‬\n     ‫وحصــل احلــادث وأنــا املتســبب يف هــذا احلــادث هكــذا أجــاب ثــم جــرى‬\n     ‫منــي االطــاع علــى أوراق املعاملــة فوجــدت بــن طياتهــا تقاريــر ســيارة‬\n     ‫املدعــي طبق ـ ًا ملــا ذكــره املدعــي فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وحيــث أقــر وصــادق املدعــى عليــه علــى دعــوى املدعــي جملــة‬\n     ‫ا وحيــث إنــه ال عــذر ملــن أقــر وحيــث إن اإلقــرار حجــة علــى‬      ‫وتفصي ـ ً‬\n     ‫املقــر لذلــك كلــه فقــد ثبــت لــدي أن املدعــى عليــه ‪ ...‬هــو املتســبب يف‬\n     ‫انقــاب ســيارة املدعــي املذكــورة يف الدعــوى حســب إقــراره وألزمتــه‬\n     ‫بتســليم املدعــي املبلــغ املدعــى بــه حــاال وقــدره خمســة وأربعــون ألــف ريال‬\n     ‫وبذلــك حكمــت وقضيــت وبعرضــه عليهمــا قــرر املدعــى القناعــة بــه‬\n     ‫أمــا املدعــى عليــه فقــرر عــدم القناعــة بــه وقــرر أنــه ســوف يقــدم ال ئحــة‬\n     ‫اعتراضيــة علــى احلكــم فأفهمتــه بــأن عليــه التقــدم للمحكمــة خــال‬\n     ‫عشــرة أيــام الســتالم نســخة مــن صــك احلكــم لالعتــراض عليــه خــال‬\n     ‫ثالثــن يومـ ًا مــن تاريــخ تســجيل الصــك وإن لــم يتقــدم باعتراضــه خــال‬\n     ‫هــذه املــدة النظاميــة فــإن حقــه يف اســتئناف احلكــم يســقط ويكتســب‬\n     ‫احلكــم القطعيــة ففهــم ذلــك وعلــى ذلــك جــرى التوقيــع وأقفلــت اجللســة‬\n     ‫متــام الســاعة التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/24‬ه ـ‬\n     ‫احلم ــد هلل وح ــده وبعـد‪...‬فق ــد اطَّ لعنــا نحــن قضــاة الدائــرة الثانية لتدقيق‬\n\n\n‫‪23‬‬\n\f‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة‬\n‫الــواردة مــن فضيلــة قاضــي احملكمــة العامــة مبحافظــة عيــون اجلــواء‬\n‫املنتــدب الشــيخ‪ ... /‬برقــم (‪ )34143796‬يف ‪1434/4/1‬هــ؛ املرفــق‬\n‫بـ ـ ـ ـ ـ ــها الصــك رق ـ ـ ـ ـ ـ ـ ــم (‪ )3422357‬يف ‪1434/1/25‬هــ؛ الصــادر مــن‬\n‫فضيلتــه؛ اخلــاص بدعــوى ‪ .....‬ضــد‪... /‬؛ بشــأن طلــب املدعــي إلــزام‬\n‫املدعــى عليــه بدفــع قيمــة تلفيــات ســيارته‪ ،‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه؛ علــى املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املدعــى بــه وقــدره‬\n‫املفصــل فيــه‪ ،‬وبدراســة الصــك‬  ‫َّ‬  ‫خمســة وأربعــون ألــف ريــال؛ علــى النحــو‬\n‫وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة علــى مــا‬\n‫حكــم بــه فضيلتــه‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪24‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":21,"source_page_end":24,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cba94a24d30b0abd20c35dc7744b8abad750cd531cb0092dc16fe24abb5376cb","normalized_text_hash":"04a4326d0e6473087d6e21ebbdd4ff8ca9504707b63607c42b62bfcc83db1514","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p21-3422357"},{"id":"71836aa1-7171-5e09-90b7-e3671ae74daa","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -تصادم سيارتني -مطالبة بأرش متلف (سيارة) - تصحيح الدعوى على الكفيل احلضوري -االستناد على قرار أهل اخلبرة (تقدير شيخ املعارض) -تضمن الكفيل احلضوري لعجزه عن إحضار مكفوله -إلزام املدعى عليه (الكفيل) بأرش تلف السيارة املقدر من أهل اخلبرة واعتبار احلكم حضوري ا .","document_number":"33480821","case_number":"32590589","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/28","year":"1434","subject":"حادث مروري -تصادم سيارتني -مطالبة بأرش متلف (سيارة) - تصحيح الدعوى على الكفيل احلضوري -االستناد على قرار أهل اخلبرة (تقدير شيخ املعارض) -تضمن الكفيل احلضوري لعجزه عن إحضار مكفوله -إلزام املدعى عليه (الكفيل) بأرش تلف السيارة املقدر من أهل اخلبرة واعتبار احلكم حضوري ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/12/28 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33480821 :‬‬\n                         ‫َر ْق ُم الدعوى‪32590589 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34281929‬تاريخه‪1434/7/29 :‬هـ‬\n\n\n      ‫حــادث مــروري ‪ -‬تصــادم ســيارتني ‪ -‬مطالبــة بــأرش متلــف (ســيارة) ‪-‬‬\n      ‫تصحيــح الدعــوى علــى الكفيــل احلضــوري ‪ -‬االســتناد علــى قــرار أهــل‬\n      ‫اخلبــرة (تقديــر شــيخ املعــارض) ‪ -‬تضمــن الكفيــل احلضــوري لعجــزه‬\n      ‫عــن إحضــار مكفولــه ‪ -‬إلــزام املدعــى عليــه (الكفيــل) بــأرش تلــف‬\n                  ‫الســيارة املقــدر مــن أهــل اخلبــرة واعتبــار احلكــم حضوري ـ ًا ‪.‬‬\n\n\n\n      ‫‪ .1‬حديــث أبــي هريــرة يف قصــة اإلســرائيلي الــذي اســتلف مــن رجــل‬\n      ‫ألــف دينــار وقــال ائتنــي بشــهود قــال‪ :‬كفــى بــاهلل شــهيدا قــال‪ :‬فأتنــي‬\n      ‫بكفيــل قــال‪ :‬كفــى بــاهلل كفيــا وقــد ترجــم لــه البيهقــي ( بــاب يف‬\n      ‫الكفالــة بالبــدن) وبهــذا القــول قــال مالــك وأبــو حنيفــة وهــو املرجــح‬\n             ‫عنــد الشــافعية وحــكاه ابــن رشــد عــن جمهــور فقهــاء األمصــار‪.‬‬\n      ‫‪ .2‬قــول ابــن فرحــون يف تبصــرة احلــكام « فــرع ‪ :‬وكذلــك يرجــع إلــى‬\n      ‫أهــل املعرفــة مبســائل الضــرر ممــا يحدثــه اإلنســان علــى جــاره أو يف‬\n                                            ‫الطرقــات و أنــواع ذلــك « (‪.)85/2‬‬\n      ‫‪ .3‬الكفيــل يضمــن مــا علــى مكفولــه إن تعــذر عليــه إحضــاره علــى‬\n      ‫الصحيــح مــن املذهب‪(.‬انظــر السلســبيل يف معرفــة الدليــل للبليهــي‬\n                                                                             ‫‪)112/2‬‬\n\n\n\n‫‪25‬‬\n\f‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه صــدم ســيارته ويطلــب‬\n‫إلزامــه بدفــع أرش التلــف ‪ -‬ثــم قــام املدعــي بتصحيــح دعــواه ضــد‬\n‫كفيــل املدعــى عليــه احلضــوري لعجــزه عــن إحضــار مكفولــه ‪ -‬جــرى‬\n‫توجيــه تبليــغ للكفيــل باحلضــور فلــم يحضــر ‪ -‬جــرى ســؤال املدعــي‬\n‫البينــة فقــرر بــأن بينتــه األوراق املرفقــة باملعاملــة ‪ -‬جــرى االطــاع علــى‬\n‫تقريــر املــرور املشــار فيــه للحــادث وجــد أن نســبة اإلدانــة علــى املدعــى‬\n‫عليــه كاملــة ‪ - %100‬جــرى االطــاع علــى تقديــر أهــل اخلبــرة ألرش‬\n‫التلــف بتقديــر قيمتهــا قبــل وبعــد احلــادث ‪ -‬طلبــت الدائــرة مــن املدعــي‬\n‫ميــن االســتظهار علــى دعــواه فحلــف ‪ -‬عليــه ولتصحيــح املدعــي وكالــة‬\n‫دعــواه علــى الكفيــل ولتخلفــه مــع تبلغــه وألن تخلفــه يجعلــه يف حكــم‬\n‫النــاكل عــن اجلــواب وقرينــة علــى دعــوى املدعــي وبنــاء علــى مــا تضمنتــه‬\n‫أوراق املعاملــة مــن بينــات رصــدت يف ضبــط القضيــة وألن األصــل عــدم‬\n‫التســديد ولبــذل املدعــي اليمــن التــي تشــرع يف جانــب أقــوى املتداعيــن‬\n‫ولقــوة جانــب املدعــي يف هــذه الدعــوى وألن للقاضــي االســتعانة بقــول‬\n‫أهــل اخلبــرة وألن الكفيــل يضمــن مــا علــى مكفولــه إن تعــذر عليــه‬\n‫إحضــاره‪ ،‬وبنــاء علــى ذلــك فقــد حكمــت الدائــرة علــى املدعــى عليــه‬\n‫الكفيــل بــأن يدفــع للمدعــي أرش التلــف املســتحق املقــدر مــن أهــل‬\n‫اخلبــرة واعتبــرت احلكــم يف حقــه حضوريــا وقــررت بعــث صــورة مــن‬\n‫صــك احلكــم للمدعــى عليــه وإفهامــه بتعليمــات االعتــراض ‪ -‬صــدق‬\n                                            ‫احلكم من محكمة االستئناف‪.‬‬\n\n\n\n                                                                                     ‫‪26‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n     ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32590589‬وتاريــخ‬\n     ‫‪1432/12/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321593797‬وتاريــخ‬\n     ‫‪1432/12/19‬ه ـ املتعلقــة بدعــوى ‪ .....‬ضــد ‪ .....‬ففــي هــذا اليــوم‬\n     ‫الســبت املوافــق‪1433/02/27‬ه افتتحــت اجللســة الســاعة ‪09 : 15‬‬\n     ‫وفيهــا حضــر املدعــي ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه ويف يــوم األحــد املوافــق‬\n     ‫‪1433/04/25‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ‪.....‬‬\n     ‫ســجل مدنــي رقــم ‪ .....‬بوكالتــه عــن ‪ .....‬الصــادرة مــن كتابــة عــدل‬\n     ‫الثانيــة بغــرب مكــة برقــم ‪ 331230‬يف ‪1433/1/1‬ه ـ املخــول لــه فيهــا‬\n     ‫املرافعــة واملدافعــة واملطالبــة باحلقــوق والتعويضــات واســتالمها الــخ ولــم‬\n     ‫يحضــر املدعــى عليــه وال مــن ميثلــه ثــم ادعــى املدعــي وكالــة قائــا إنــه‬\n     ‫بتاريــخ ‪1432/12/4‬ه ـ ومبنطقــة الشــرائع وقــع حــادث مــروري عبــارة‬\n     ‫عــن تصــادم حيــث قــام املدعــى عليــه بصــدم ســيارة موكلــي مــن اجلهــة‬\n     ‫اليمنــى مــا أحلــق بهــا تلفيــات وأضــرار وقــد أديــن املدعــى عليــه بنســبة‬\n     ‫‪ % 100‬املســئولية الكاملــة عــن ذلــك احلــادث كمــا هــو موضــح مبحضــر‬\n     ‫النســبة املعتمــد مــن قبــل شــعبة احلــوادث بــإدارة مــرور العاصمــة املقدســة‬\n     ‫املرفــق باملعاملــة وقــد قــدرت مســتحقاتي املاليــة املترتبــة علــى املدعــى‬\n     ‫عليــه لقــاء ذلــك احلــادث الــذي تســبب فيــه مبلــغ قــدره واحــد وعشــرون‬\n     ‫ألــف ريــال لــذا فإنــي أطلــب احلكــم علــى املدعــى عليــه بدفع مســتحقاتي‬\n\n‫‪27‬‬\n\f‫املاليــة واملتمثلــة يف مبلــغ واحــد وعشــرين ألــف ريــال لقــاء احلــادث الــذي‬\n‫وصفــت وقائعــه يف دعــواي والــذي تســبب فيــه املدعــى عليــه هــذه دعــواي‬\n‫وأســأله اجلــواب احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق‬\n‫‪1433/09/12‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 00‬وفيهــا حضــر املدعي‬\n‫وكالــة ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وكانــت قــد وردتنــا‬\n‫أوراق التبليــغ برقــم ‪ 32/33/242818‬يف ‪1433/2/7‬ه ـ املتضمــن (لقــد‬\n‫ســلم التبليــغ لكفيلــه ‪...................‬وأفيــد أنــه لــدى املدعــى عليــه ســفر‬\n‫خــارج اململكــة يف تاريــخ اجللســة آمــل حتديــد موعــد جديد)‪.‬إ‪.‬هــ‪ .‬وتبليــغ‬\n‫رقــم ‪ 33/787443‬يف ‪1433/4/26‬ه ـ املتضمــن أنــه جــرى تســليم صــورة‬\n‫التبليــغ للمدعــو ‪ ................... /‬صفتــه موظــف باملؤسســة)‪.‬إ‪.‬هـ‪ .‬ثــم قــرر‬\n‫املدعــي وكالــة قائــا إنــي أطلــب تصحيــح دعــواي هــذه وتوجيههــا ضــد‬\n‫كفيــل املدعــى عليــه ‪ ...............‬حيــث كفلــه كفالــة حضوريــة هكــذا‬\n‫قــال ثــم جــرى تصفــح أوراق املعاملــة فوجــدت كفالــة حضوريــة علــى لفــة‬\n‫رقــم (‪ )3‬موافقــة ملــا عطــف عليهــا عليــه أمــرت بإعــادة إبــاغ املدعــو ‪/‬‬\n‫‪ ..............‬املذكــور للحضــور يف املوعــد احملــدد يف يــوم الثالثــاء املوافــق‬\n‫‪1433/11/23‬ه ـ الســاعة ‪ 10 : 30‬لإلجابــة عــن دعــوى املدعــي وكالــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1433/9/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء ‪1433/11/23‬ه ـ‬\n‫أفتتحــت اجللســة متــام الســاعة ‪11 : 00‬وفيهــا حضــر املدعــي وكالــه‬\n‫وحضــر حلضــوره املدعــى ‪........................‬ســعودي اجلنســية بالســجل‬\n‫املدنــي رقــم‪ .......................‬ثــم قــرر األخيــر قائــا لقــد طلــب موكلــي‬\n‫تصحيــح دعــواي يف اجللســة املاضيــة علــى املدعــو‪ ......................‬حيــث‬\n\n\n                                                                                        ‫‪28‬‬\n\f     ‫أنــي أطلــب احلكــم عليــه بإلزامــه بدفــع املبلــغ املدعــى بــه وقــدره‬\n     ‫واحــد وعشــرون ألــف ريــال لقــاء كفالتــه املتســبب يف احلــادث املدعــو‬\n     ‫‪ .................. /‬كفالــه حضوريــه حيــث لــم يحضــر بذاتــه ولــم يحضــر‬\n     ‫مكفولــه هكــذا قــال وبتصفــح أوراق املعاملــة وجــدت ضمــن طياتهــا‬\n     ‫ورقــة تبليــغ برقــم ‪ 5/138/20‬املتضمنــة اســم املســتلم‪.......................‬‬\n     ‫صفتــه كفيــل املدعــى عليــه ووكيلــه وجدتهــا تضمنــت العبــارة التاليــة‬\n     ‫علم ـ ًا أن لــدي موعــد ســفر خــارج اململكــة يف تاريــخ اجللســة أ‪.‬ه ـ وقــد‬\n     ‫حــددت يف ورقــة التبليــغ جلســة يــوم الســبت ‪1433/2/27‬ه ـ ثــم ســألت‬\n     ‫املدعــي عــن بينتــه علــى دعــواه فأجــاب بقولــه إن بينتــي هــي مــا ورد‬\n     ‫يف أوراق املعاملــة وأطلــب الرجــوع إليهــا هكــذا قــال وبتصفــح أوراق‬\n     ‫املعاملــة وجــدت ضمــن طياتهــا محضــر نســبة إدانــة علــى اللفــة رقــم ‪16‬‬\n     ‫رقــم بــدون تاريــخ بــدون ويتضمــن بعــد االطــاع علــى األوراق اخلاصــة‬\n     ‫باحلــادث املــروري الــذي وقــع بتاريــخ ‪1432/12/4‬ه ـ اتضــح لنــا أنــه‬\n     ‫يــدان يف احلــادث املدعــو ‪ .................‬ســوداني اجلنســية باإلقامــة رقــم‬\n     ‫………………‪ .‬ســائق الســيارة مــن نــوع مرســيدس راس رقــم اللوحــة‬\n     ‫‪ .....................‬نســبة اإلدانة ‪ %100‬واملدعو ………………… ســعودي‬\n     ‫اجلنســية رقــم الهويــة ‪ ......................‬ســائق الســيارة مــن نــوع كامــري‬\n     ‫رقــم اللوحــة ‪ ...................‬وذلــك لألســباب اآلتيــة مباشــرة الطــرف األول‬\n     ‫للصــدم مبقدمــة ســيارته ودخولــه يف مســار الطريــق الثانــي وعــدم‬\n     ‫إعطــاء األفضليــة ملــن يســير يف مســاره الصحيــح وبعــض الطــرف الثانــي‬\n     ‫مــن النســبة كونــه يســير يف مســاره الصحيــح ولــم يرتكــب أي خطــأ‬\n     ‫أدى إلــي وقــوع احلــادث توقيــع ضابــط القضيــة ‪...............‬ضابــط محقــق‬\n     ‫‪ ..................‬رئيــس شــعبة احلــوادث املكلــف ‪ .............‬أ‪.‬ه ـ كمــا وجــدت‬\n\n\n‫‪29‬‬\n\f‫تقديــر ًا لشــيخ املعــارض وطائفــة داللــي حراجــات الســيارات العاصمــة‬\n‫املقدســة لفــة ‪12‬برقــم ‪ 5414‬وتاريــخ ‪1432/12/4‬ه ـ املتضمــن أن‬\n‫ســعر الســيارة الكامــري موديــل ‪ 2006‬ورقــم لوحتهــا‪ ............... ...‬قبــل‬\n‫احلــادث يقــدر مببلــغ تســعة وعشــرون ألــف ريــال تقريب ـ ًا وبعــد احلــادث‬\n‫يقــدر مببلــغ ثمانيــة آالف وخمســمائة ريــال تقريبـ ًا أ‪.‬ه ـ ثــم ســألت املدعي‬\n‫هــل لديــه مزيــد بينــة فأجــاب بالنفــي فطلبــت منــه اليمــن علــى صحــة‬\n‫ا واهلل العظيــم الــذي ال إلــه إال هــو عالــم الغيــب‬        ‫دعــواه فحلــف قائ ـ ً‬\n‫والشــهادة بأنــه بتاريــخ ‪1432/12/4‬ه ـ ومبنطقــة الشــرائع وقــع حــادث‬\n‫مــروري عبــارة عــن تصــادم حيــث قــام املدعــو ‪ .............................‬بصــدم‬\n‫ســيارتي مــن اجلهــة اليمنــى وأحلــق بهــا تلفيــات وأضــرار وقــد أديــن بنســبة‬\n‫‪ %100‬عــن ذلــك احلــادث وقــد قــدرت مســتحقاتي املاليــة املترتبــة عليــه‬\n‫لقــاء ذلــك احلــادث الــذي تســبب فيــه مبلــغ قــدره واحــد وعشــرون ألــف‬\n‫ريــال وقــد كفلــه املدعــو ‪ ................‬كفالــة حضوريــه و غرميــه وأنــه‬\n‫لــم يصلنــي شــيء مــن املبلــغ املدعــى بــه ولــم أبــرئ منــه واهلل العظيــم‬\n‫) فبنــاء علــى مــا تقــدم مــن الدعــوى ولتصحيــح املدعــي وكالــة دعــواه‬\n‫وطلــب املدعــي أمضــاء ذلــك وتوجيههــا علــى الكفيــل ولتخلفــه مــع تبلغــه‬\n‫وألن تخلفــه يجعلــه يف حكــم النــاكل عــن اجلــواب وقرينــة علــى دعــوى‬\n‫املدعــي وبنــاء علــى مــا تضمنتــه أوراق املعاملــة مــن بينــات رصــدت بعاليــه‬\n‫و ألن األصــل عــدم التســديد ولبــذل املدعــي اليمــن التــي تشــرع يف جانب‬\n‫أقــوى املتداعيــن ولقــوة جانــب املدعــي يف هــذه الدعــوي وألنــه قــد يحتاج‬\n‫محــل النــزاع املعــروض علــى احملكمــة الــى رأي أهــل اخلبــرة فللقاضــي‬\n‫االســتعانة بقولهــم ملــا لهــم مــن عالمــات حســية متكنهــم مــن املعرفــة ويف‬\n‫ذلــك يقــول ابــن فرحــون يف تبصــرة احلــكام ( فــرع ‪ :‬وكذلــك يرجــع‬\n\n\n                                                                                         ‫‪30‬‬\n\f     ‫الــى أهــل املعرفــة مبســائل الضــرر ممــا يحدثــة اإلنســان علــى جــاره أو يف‬\n     ‫الطرقــات و أنــواع ذلــك ) (‪ )85/2‬ولرضــى املدعى عليه نصار بالكفالة‬\n     ‫والتــي تظهــر يف كفالتــه للمتســبب ‪...................‬يحررهــا كمــا يف اللفــة‬\n     ‫الثالثــة مــن أوراق املعاملــة و ألن الكفالــة تصــح بــكل عــن مضمونــه‬\n     ‫وببــدن مــن عليــه ديــن و يف صحيــح البخــاري مــن حديــث أبــي هريــره‬\n     ‫يف قصــة اإلســرائيلي الــذي اســتلف مــن رجــل ألــف دينــار وقــال ائتنــي‬\n     ‫بشــهود قــال كفــى بــاهلل شــهيدا قــال فأتنــي بكفيــل قــال كفــى بــاهلل‬\n     ‫كفيــا وقــد ترجــم لــه البيهقــي ( بــاب يف الكفالــة بالبــدن) وبهــذا‬\n     ‫القــول قــال مالــك وأبــو حنيفــه وهــو املرجــح عنــد الشــافعية وحــكاه‬\n     ‫ابــن رشــد عــن جمهــور فقهــاء األمصــار وعلــى الصحيــح مــن املذهــب إن‬\n     ‫تعــذر علــى الكفيــل إحضــار املكفــول ضمــن مــا عليــه وهــو اختيــار‬\n     ‫الشــيخ أنظــر السلســبيل حاشــية علــى زاد املســتقنع ‪ .‬البليهــي ‪.112/2‬‬\n     ‫بنــاء علــى ذلــك فقــد حكمــت علــى املدعــى عليــه ‪............................‬‬\n     ‫بــأن يدفــع للمدعــي ‪ .........................‬املبلــغ املدعــى بــه و قــدره واحــد و‬\n     ‫عشــرون ألــف ريــال وبذلــك حكمــت واعتبرتــه حضوريــا يف حــق املدعــى‬\n     ‫عليــه وســوف يتــم إبالغــه بنســخه مــن احلكــم لتقــدمي مــا لديــه حيالــه‬\n     ‫مــن اعتــراض خــال ثالثــن يومــا مــن تاريــخ االســتالم فــأن لــم يفعــل‬\n     ‫خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب احلكــم القطعيــة‬\n     ‫وبــاهلل التوفيــق وصــل اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫حــرر يف ‪1433/11/23‬ه ـ احلمــد هلل وحــده وبعــد لــدي أنــا ‪...................‬‬\n     ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة القائــم بعمــل فضيلــة‬\n     ‫الشــيخ ‪ ...................‬خــال فتــرة إجازتــه حيــث عــادت أوراق املعاملــة مــن‬\n     ‫محكمــة االســتئناف باخلطــاب رقــم ‪ 321593797‬يف ‪1434/8/21‬ه ـ‬\n\n\n‫‪31‬‬\n\f‫رفقهــا الصــك الشــرعي رقــم ‪ 33480821‬يف ‪1433/12/28‬ه ـ مظهــر ًا‬\n‫عليــه بقــرار الدائــرة احلقوقيــة اخلامســة مبحكمــة االســتئناف رقــم‬\n‫‪ 34281929‬يف ‪1434/7/29‬ه ـ املتضمــن أنــه بدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــررت باألكثريــة املوافقــة علــى احلكم‬\n‫‪ .‬قاضــي اســتئناف ختــم وتوقيــع‪ ( ................... /‬لــي وجهــة نظــر ‪ /‬قاضي‬\n‫اســتئناف ختــم وتوقيــع ‪ / ................ /‬رئيــس اســتئناف ختــم وتوقيــع‬\n‫‪ ......................./‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1434/10/14‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n‫‪321593797‬وتاريــخ ‪1434/7/5‬ه املرفــق بهــا الصــك رقــم ‪33480821‬‬\n‫وتاريخ‪1433/12/28‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪..................../‬‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة املتضمــن دعــوى‪............/‬‬\n‫‪................‬ســعودي اجلنســية ضد ‪ ........................../‬ســوداني اجلنســية يف‬\n‫إتــاف ممتلــكات‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا باألكثريــة املوافقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪32‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":25,"source_page_end":32,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4f253507806c1bd9f26bae6b1e834aab2fe40d4cee0d3244960f81ba0382fe66","normalized_text_hash":"70804a09b3f995b3d6d0589c2fe0aac4f1c66e873f1920088d97c34043e5bc7e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p25-33480821"},{"id":"a23c165c-f1be-5498-beed-207798ca3ab0","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -مطالبة املؤجر بأرش التلف من املستأجر لتعديه بتسليم السيارة لغيره من غير إذن منها مخالف ا شرط العقد -دفع املدعى عليه بعدم التعدي وأن سبب احلادث خلل فني -احلكم بإلزام املدعى عليه بدفع االرش -رفع املعاملة حملكمة الاستئناف لتعذر تسليم احلكم للمدعى عليه.","document_number":"33415596","case_number":"33226640","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/19","year":"1434","subject":"حادث مروري -مطالبة املؤجر بأرش التلف من املستأجر لتعديه بتسليم السيارة لغيره من غير إذن منها مخالف ا شرط العقد -دفع املدعى عليه بعدم التعدي وأن سبب احلادث خلل فني -احلكم بإلزام املدعى عليه بدفع االرش -رفع املعاملة حملكمة الاستئناف لتعذر تسليم احلكم للمدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/9/19 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33415596 :‬‬\n                        ‫َر ْق ُم الدعوى‪33226640 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34204163‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬مطالبــة املؤجــر بــأرش التلــف مــن املســتأجر لتعديــه‬\n     ‫بتســليم الســيارة لغيــره مــن غيــر إذن منهــا مخالفـ ًا شــرط العقــد ‪ -‬دفــع‬\n     ‫املدعــى عليــه بعــدم التعــدي وأن ســبب احلــادث خلــل فنــي ‪ -‬احلكــم‬\n     ‫بإلــزام املدعــى عليــه بدفــع االرش ‪ -‬رفــع املعاملــة حملكمــة االســتئناف‬\n                                         ‫لتعــذر تســليم احلكــم للمدعــى عليــه‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله تعالى‪« :‬يا أيها اللذين آمنوا أوفوا بالعقود»‪.‬‬\n     ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم‪« :‬املســلمون علــى شــروطهم»رواه أبــو داود‬\n                           ‫وأحمــد والترمــذي وقــال هــذا حديــث حســن صحيح‪.‬‬\n     ‫‪ .3‬قــول ابــن رشــد ‪-‬رحمــه اهلل‪ -‬يف بدايــة املجتهــد ‪« : 231/2‬وال خــاف‬\n     ‫أنهــا ‪ -‬يعنــي الدابــة املســتأجرة ‪ -‬إذا تلفــت باملســافة املتعــداة أنــه ضامــن‬\n                                                                               ‫لها»أ‪.‬هـ‪.‬‬\n     ‫‪ .4‬وقــول ابــن قدامــة ‪-‬رحمــه اهلل‪ -‬يف املغنــي ‪ ... « : 79/5‬فأمــا إذا تلفــت‬\n     ‫حالــة تعــدٍ ولــم يكــن صاحبهــا مــع راكبهــا فــا خــاف يف ضمانهــا‬\n                                                                     ‫بكمــال القيمــة»‪.‬‬\n     ‫‪ .5‬الفقــرة (‪ )5/176‬مــن اللوائــح التنفيذيــة لنظــام املرافعــات الشــرعية‬\n     ‫ونصهــا «إذا تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى احملكــوم‬\n     ‫عليــه أو وكيلــه يرفــع احلكــم إلــى محكمــة التمييــز بــدون الئحــة‬\n                                                                          ‫اعتراضيــة»‪.‬‬\n‫‪33‬‬\n\f‫أقامــت شــركة دعــوى علــى املدعــى عليــه بأنــه اســتأجر منهــا ســيارة‬\n‫فــأذن البنــه بقيادتهــا فانقلــب بهــا وملــا تضمنــه أحــد بنــود العقــد مــن أن‬\n‫املســتأجر يضمــن كل مــا يلحــق الســيارة مــن تلــف إذا مكــن غيــره مــن‬\n‫قيادتهــا فهــي تطلــب إلــزام املدعــى عليــه بدفــع أرش التلــف وأجــرة نقــل‬\n‫الســيارة مــن موقــع احلــادث ‪ -‬أقــر املدعــى عليــه بالعقــد وأنــه مكــن ابنــه‬\n‫مــن قيــادة الســيارة ودفــع بــأن احلــادث كان خللــل فنــي يف الســيارة حيــث‬\n‫انفتــح عليــه واقــي احملــرك أثنــاء الســير بهــا فحجبــت عنــه الرؤيــة ممــا‬\n‫أدى النقالبــه بهــا ‪ -‬طعــن املدعــى عليــه أيضــا بتقديــر أهــل اخلبــرة بأنهــم‬\n‫لــم يشــاهدوا العــن املتلفــة ‪ -‬تخلــف املدعــى عليــه عــن احلضــور اجللســة‬\n‫بعــد تبلغــه لشــخصه ‪ -‬جــرى اطــاع الدائــرة علــى وثيقــة العقــد ومــا‬\n‫تضمنتــه مــن شــروط منهــا عــدم الســماح لغيــر املســتأجر بقيــادة الســيارة‬\n‫وعلــى تقديــر شــيخ املعــارض ورصــد مضمونهمــا بضبــط القضيــة ‪ -‬عليه‬\n‫وألن الشــركة املدعيــة اشــترطت علــى املدعــى عليــه أن يســتويف املنفعــة‬\n‫املؤجــرة بنفســه أو مبــن يفــوض تفويضـ ًا رســمي ًا مــن قبلهــم وألن األصــل‬\n‫يف الشــروط اجلــواز والصحــة ولقولــه تعالــى‪« :‬يــا أيهــا الذيــن آمنــوا أوفــوا‬\n‫بالعقــود» ولقولــه صلــى اهلل عليــه وســلم ‪ »:‬املســلمون علــى شــروطهم»‬\n‫رواه أبــو داود وأحمــد والترمــذي وقــال هــذا حديــث حســن صحيــح ‪-‬‬\n‫وألن املدعــى عليــه أقــر بعــدم تفويــض ابنــه تفويضـ ًا رســمي ًا وألن الضمان‬\n‫منــوط بالتعــدي‪ ،‬واملدعــى عليــه قــد خالــف الشــرط فتعتبــر يــده واحلالــة‬\n‫هــذه يدعاديــة قــال ابــن رشــد رحمــه اهلل يف بدايــة املجتهــد ‪« : 231/2‬وال‬\n‫خــاف أنهــا ‪-‬يعنــي الدابــة املســتأجرة ‪-‬إذا تلفــت باملســافة املتعــداة أنــه‬\n\n                                                                                       ‫‪34‬‬\n\f     ‫ضامــن لهــا» أ‪.‬ه ـ وقــال ابــن قدامة‪-‬رحمــه اهلل‪ -‬يف املغنــي ‪... « : 79/5‬‬\n     ‫فأمــا إذا تلفــت حالــة تعــدٍ ولــم يكــن صاحبهــا مــع راكبهــا فــا خــاف‬\n     ‫يف ضمانهــا بكمــال القيمــة» ‪ ،‬لــذا كلــه فقــد حكمــت الدائــرة علــى‬\n     ‫املدعــى عليــه بــأن يســلم الشــركة املدعيــة أرش تلــف الســيارة محــل‬\n     ‫الدعــوى مــع تكلفــة نقلهــا ‪ -‬اعتبــرت الدائــرة احلكــم حضوريــا وقــررت‬\n     ‫بعــث صــورة الصــك للمدعــى عليــه وإفهامــه بتعليمــات االعتــراض ‪-‬‬\n     ‫وردت اإلفــادة مــن محضــر اخلصــوم بالوصــول ملنــزل املدعــى عليــه عــدة‬\n     ‫مــرات يف أوقــات مختلفــة ولــم يعثــر عليــه وأفــاد أحــد املجاوريــن أنــه لــم‬\n     ‫يــره منــذ فتــرة طويلــة عليــه وبنــاء علــى الفقــرة (‪ )5/176‬مــن اللوائــح‬\n     ‫التنفيذيــة لنظــام املرافعــات الشــرعية ونصهــا» إذا تعــذر تســليم نســخة‬\n     ‫صــك احلكــم الغيابــي إلــى احملكــوم عليــه أو وكيلــه يرفــع احلكــم‬\n     ‫إلــى محكمــة التمييــز بــدون الئحــة اعتراضيــة» عليــه فقــد قــررت إحلــاق‬\n     ‫ذلــك بالصــك وســجله ورفعــه حملكمــة االســتئناف ‪ -‬صــدق احلكــم مــن‬\n                                                                  ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......................‬القاضــي يف احملكمــة‬\n     ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33226640‬وتاريــخ‬\n     ‫‪1433/03/30‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33604249‬وتاريــخ‬\n     ‫‪1433/03/30‬ه ـ حضــر ‪ .......................‬ســجل مدني رقــم ‪.....................‬‬\n     ‫بصفتــه وكيــا عــن ‪ ......................‬الوكيــل عــن ‪...........................‬‬\n     ‫مديــر الشــركة ‪ ...‬للبيــع بالتقســيط احملــدودة مبوجــب صــك الوكالــة‬\n\n‫‪35‬‬\n\f‫الصــادر مــن كتابــة العــدل الثانيــة بشــمال جــدة برقــم ‪ 99012‬يف‬\n‫‪ /12/2‬واملخولــة لــه إقامــة وســماع الدعــاوي واملدافعــة واملرافعــة وتقــدمي‬\n‫البينــات وطلــب اليمني‪....‬إلــخ كمــا حضــر املدعــى عليــه ‪.......................‬‬\n‫ا‬\n‫ســجل مدنــي رقــم ‪ ، ................‬وبســؤال املدعــي عــن دعــواه أجــاب قائـ ً‬\n‫‪ :‬إن املدعــى عليــه اســتأجر منــا ســيارة يف ‪1429/8/18‬ه ـ نــوع ‪ ...‬وارد‬\n‫‪ ...‬رقــم الهيــكل ‪ .............‬رقــم اللوحــة ‪..............‬اللــون ‪ ...‬مبوجــب العقــد‬\n‫رقــم ‪ ....‬ملــدة ثمانيــة وأربعــن شــهر ًا ميالديــا ً تبــدأ مــن ‪2008/9/1‬م حتــى‬\n‫‪2012/8/1‬م بأجــرة إجماليــة قدرهــا ســتة وثمانــون ألف ـ ًا وأربعمائــة‬\n‫ريــال دفــع منهــا عنــد العقــد ألــف ريــال واألجــرة الشــهرية قدرهــا ألــف‬\n‫وثمامنائــة ريــال كمــا أن للمدعــى عليــه حــق متلك الســيارة بعــد انتهاء مدة‬\n‫التأجيــر مبوجــب عقــد جديــد يكتــب يف حينــه وقــد وقــع حــادث أثنــاء‬\n‫مــدة التأجيــر بتاريــخ ‪1431/3/6‬ه ـ علــى طريــق الســيل باجتــاه الطائــف‬\n‫بقيــادة ابــن املدعــى عليــه ‪ ........‬وكان احلــادث مــن طــرف واحــد وذلــك‬\n‫بانقــاب الســيارة وتلفهــا بالكامــل وقــدرت مــن قبــل شــيخ املعــارض قبل‬\n‫احلــادث مببلــغ قــدره ثالثــة وأربعــون ألــف ريــال وبعــد احلــادث مببلــغ قــدره‬\n‫اثنــا عشــر ألــف ريــال أطلــب إلــزام املدعــى عليــه بتســليم موكلتــي أرش‬\n‫التلفيــات وقــدره واحــد وثالثــون ألــف ريــال باإلضافــة إلــى مائتــي ريــال‬\n‫فاتــورة نقــل الســيارة مــن الشــركة إلــى شــيخ املعــارض وذلــك أن املدعــى‬\n‫عليه ســلم ابنه الســيارة بغير تفويض رســمي من قبل موكلتي وذلك أن‬\n‫الفقــرة الثالثــة مــن البنــد اخلامــس للعقــد تنــص علــى أن (يتحمــل الطــرف‬\n‫الثانــي تكاليــف إصــاح الســيارة املؤجــرة وتكاليــف األضــرار التــي‬\n‫تلحــق بركابهــا ســواء أكانــت إصابــات أوديــات وجميــع التكاليــف‬\n‫املترتبــة للغيــر مبــا يف ذلــك الديــة واإلصابــات وذلــك يف حالــة مــا إذا وقــع‬\n\n\n                                                                                            ‫‪36‬‬\n\f     ‫احلــادث وكان ســائق الســيارة محــل العقــد غيــر مفــوض بصفــة رســمية‬\n     ‫مــن قبــل الطــرف األول بقيادتهــا ســواء أكان ذلــك بعلــم الطــرف الثانــي‬\n     ‫أم بــدون علمــه) إ‪.‬ه ـ واملدعــى عليــه لــم يفــوض ابنــه تفويضـ ًا رســمي ًا هــذه‬\n     ‫ا ‪ :‬مــا ذكــره‬    ‫دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫املدعــي مــن االســتئجار بالعقــد واملــدة واألقســاط املذكــورة و قيــادة‬\n     ‫ابنــي للســيارة بــدون تفويــض مــن الشــركة ووقــوع احلــادث باالنقــاب‬\n     ‫فصحيــح إال أن ســبب احلــادث خلــل فنــي وذلــك أن كبوت الســيارة انفتح‬\n     ‫أثنــاء القيــادة فحجــب الرؤيــة فوقــع االنقــاب كمــا أننــي غيــر موافــق‬\n     ‫علــى تقديــر شــيخ املعــارض وذلــك ألن شــيخ املعــارض لم يشــاهد الســيارة‬\n     ‫قبــل احلــادث وعليــه فــا أوافقهــم علــى طلبهــم ألنهــم ال يســتحقون شــيئ ًا‬\n     ‫هكــذا أجــاب‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة ولــم يحضــر‬\n     ‫املدعــى عليــه وقــد جــرى االطــاع علــى العقــد بــن الطرفــن املطبوع على‬\n     ‫أوراق الشــركة ‪ ...................‬برقــم ‪ ...‬وتاريــخ ‪1429/8/18‬ه ــواملتضمن‬\n     ‫تأجيــر الشــركة املدعيــة علــى املدعــى عليــه الســيارة محــل الدعــوى‬\n     ‫للمــدة واألجــرة املذكورتــن‪ ،‬كمــا جــرى االطــاع علــى الفقــرة الثالثــة‬\n     ‫مــن البنــد اخلامــس فوجدتهــا طبــق مــا ذكــره املدعــي‪ ،‬كمــا جــرى‬\n     ‫االطــاع علــى الفقــرة الثانيــة عشــرة مــن البنــد تاســع ًا ونصهــا (ال يعــد‬\n     ‫هــذا العقــد تفويض ـ ًا مــن الطــرف األول للطــرف الثانــي أو ألي شــخص‬\n     ‫آخــر بقيــادة الســيارة املؤجــرة ‪ ،‬مــا لــم يحمــل الطرف الثاني أو الشــخص‬\n     ‫اآلخــر املفــوض بالقيــادة رخصــة قيــادة ســارية املفعــول وتفويضـ ًا كتابيـ ًا‬\n     ‫ال عــن‬ ‫ســاري املفعــول مــن الطــرف األول بقيــادة الســيارة املؤجــرة مســتق ً‬\n     ‫هــذا العقــد ‪ ،‬موقع ـ ًا ومختوم ـ ًا مــن قبــل الطــرف األول) ‪ ،‬كمــا جــرى‬\n     ‫االطــاع علــى تقديــر شــيخ املعــارض برقــم ‪ 0782‬يف ‪1433/3/26‬ه ـ‬\n\n\n‫‪37‬‬\n\f‫للســيارة محــل الدعــوى واملتضمــن تقديرهــا قبــل احلــادث بثالثــة وأربعــن‬\n‫ألــف ريــال وبعــد احلــادث باثنــي عشــر ألــف ريــال‪ ،‬فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ومــا جــرى االطــاع عليــه مــن العقــد بــن الطرفــن‬\n‫وتقدير شــيخ املعارض ومبا أن الشــركة املدعية اشــترطت على املدعى‬\n‫عليــه أن يســتويف املنفعــة املؤجــرة بنفســه أو مبــن يفــوض تفويضـ ًا رســمي ًا‬\n‫مــن قبلهــم ومبــا أن األصــل يف الشــروط يف العقــود اجلــواز والصحــة لقوله‬\n‫تعالــى ‪( :‬يــا أيهــا اللذيــن آمنــوا أوفــوا بالعقــود ) ولقولــه صلــى اهلل عليــه‬\n‫وســلم ‪( :‬املســلمون علــى شــروطهم) رواه أبــو داود وأحمــد والترمــذي‬\n‫وقــال هــذا حديــث حســن صحيــح إ‪.‬ه ـ ‪،‬ومبــا أن املدعــى عليــه صــادق‬\n‫علــى دعــوى املدعــي يف عــدم تفويــض ابنــه تفويض ـ ًا رســمي ًا والضمــان‬\n‫منــوط بالتعــدي واملدعــى عليــه قــد خالــف مــا تشــارط عليــه الطرفــان‬\n‫فتعتبــر يــده واحلالــة هــذه يــد عاديــة قــال ابــن رشــد رحمــه اهلل يف بدايــة‬\n‫املجتهــد ‪ ( : 231/2‬وال خــاف أنهــا «يعنــي الدابــة املســتأجرة « إذا تلفــت‬\n‫باملســافة املتعــداة أنــه ضامــن لهــا ( إ‪.‬ه ـ وقــال ابــن قدامــه رحمــه اهلل يف‬\n‫املغنــي ‪ ... ( : 79/5‬فأمــا إذا تلفــت حالــة تعــدٍ ولــم يكــن صاحبهــا مــع‬\n‫راكبهــا فــا خــاف يف ضمانهــا بكمــال القيمــة) ‪ ،‬لــذا كلــه فقــد‬\n‫حكمــت علــى املدعــى عليــه بــأن يســلم الشــركة املدعيــة أرش تلفيــة‬\n‫الســيارة محــل الدعــوى مــع تكلفــة نقلهــا وقــدره واحــد وثالثــون ألف ـ ًا‬\n‫ومائتــا ريــال ويعتبــر هــذا احلكــم يف حــق املدعــى عليــه حضوريـ ًا وقــررت‬\n‫بعــث نســخة مــن صــك احلكــم للمدعــى عليــه لالعتــراض يف مــدة ال‬\n‫تتجــاوز ثالثــن يوم ـ ًا مــن تاريــخ اســتالمه للنســخة فــإذا انقضــت املــدة‬\n‫ولــم يقــدم اعتراضــه يســقط حقــه يف االعتــراض ويكتســب احلكــم‬\n‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                         ‫‪38‬‬\n\f                                            ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/9/3‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد بعــث نســخة صك احلكــم وردنا خطاب محضري‬\n     ‫اخلصــوم رقــم ‪ 33/2274915‬يف ‪1434/2/4‬ه ـ واملتضمــن تعــذر تســليم‬\n     ‫صــورة الصــك للمدعــى عليــه ‪ ....................‬وأنــه ( مت الوصــول ملنــزل‬\n     ‫املذكــور عــدة مــرات يف أوقــات مختلفــة ولــم جنــد املذكــور وأفــاد أحــد‬\n     ‫املجاوريــن أنــه لــم يــرى املذكــور منــذ فتــرة طويلــة) ‪ ،‬وبنــاء علــى املــادة‬\n     ‫‪ 5/176‬مــن اللوائــح التنفيذيــة لنظــام املرافعــات الشــرعية التــي تنــص‬\n     ‫علــى ( أنــه إذا تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى احملكــوم‬\n     ‫عليــه أو وكيلــه يرفــع احلكــم إلــى محكمــة التمييــز بــدون الئحــة‬\n     ‫اعتراضيــة )‪ ،‬عليــه فقــد قــررت إحلــاق ذلــك بالصــك وســجله ورفعــه‬\n     ‫حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                  ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/9‬ه‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪:‬‬\n     ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n     ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪33604249‬‬\n     ‫وتاريــخ ‪1434/4/16‬ه ـ املرفــق بهــا الصــك رقــم ‪ 33415596‬وتاريــخ‬\n     ‫‪1433/9/19‬ه ـ الصــادر مــن فضيلــة الشــيخ‪...................... /‬القاضــي‬\n     ‫باحملكمــة العامــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى ‪......................‬‬\n     ‫ضــد‪.................. /‬يف دعــوى حقوقيــة احملكــوم فيــه مبــا دون باطنــه‬\n     ‫بدراســة احلكــم وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم واهلل‬\n        ‫املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":33,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"368b07f62287efb06dcf68f5c9016831214191a6c80aa606585a09e51cbe19c8","normalized_text_hash":"818de9f2c817a8f16ce1558db4a63f1e722d103a1b8b42eb5121df77af09a0b4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p33-33415596"},{"id":"09bc636d-18e4-5cc6-b78d-6753a4dc562b","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -اصطدام سيارتني -سائق السيارة ليس مالكها - االختاف يف تقدير األرش -رفض الصلح أو التنازل عن أي مبلغ -األخذ يف الغرم باألقل -التزام مالك السيارة مبا ترتب على سائقها -االستناد إلى تقرير املرور وتقييم أهل اخلبرة يف تقدير","document_number":"33357527","case_number":"33143924","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف -جري تسليم املبلغ احملكوم به وبذلك انتهت القضية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/27","year":"1434","subject":"حادث مروري -اصطدام سيارتني -سائق السيارة ليس مالكها - االختاف يف تقدير األرش -رفض الصلح أو التنازل عن أي مبلغ -األخذ يف الغرم باألقل -التزام مالك السيارة مبا ترتب على سائقها -االستناد إلى تقرير املرور وتقييم أهل اخلبرة يف تقدير","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/27 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33357527 :‬‬\n                    ‫َر ْق ُم الدعوى‪33143924 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 3460445‬تاريخه‪1434/3/11 :‬هـ‬\n\n\n ‫حــادث مــروري ‪ -‬اصطــدام ســيارتني ‪ -‬ســائق الســيارة ليــس مالكهــا ‪-‬‬\n ‫االختــاف يف تقديــر األرش ‪ -‬رفــض الصلــح أو التنــازل عــن أي مبلــغ‬\n ‫‪ -‬األخــذ يف الغــرم باألقــل ‪ -‬التــزام مالــك الســيارة مبــا ترتــب علــى‬\n ‫ســائقها ‪ -‬االســتناد إلــى تقريــر املــرور وتقييــم أهــل اخلبــرة يف تقديــر‬\n                                                                         ‫املبلــغ ‪.‬‬\n\n\n\n ‫قــول الســيوطى رحمــه اهلل ‪( :‬ويؤخــذ يف الغــرم باألقــل ‪ ،‬ولــه مأخــذان‪:‬‬\n ‫أحدهمــا ‪ :‬وهــو األظهــر أن األقــل متيقــن والزائــد مشــكوك فيــه ‪.‬‬\n         ‫والثانــي ‪ :‬أن التــي شــهدت باألقــل رمبــا أطلعــت علــى عيــب )‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي علــى املدعــى عليــه بأنــه كان يســير بســيارته يف الطريــق‬\n ‫العــام وجــاء أخ املدعــى عليــه وصــدم بــه مــن اخللــف بســيارة عائــدة‬\n ‫ملكيتهــا للمدعــى عليــه ‪ -‬أديــن أخ املدعــى عليــه بنســبة اخلطــأ كاملــة‬\n ‫‪ -‬مت تقديــر تلفيــات ســيارة املدعــى بثــاث تقديــرات متفاوتــة ‪ -‬طلــب‬\n ‫املدعــي إلــزام املدعــى عليــه بدفــع التقديــر األوســط ‪ -‬أقــر املدعــى عليــه‬\n ‫مبــا جــاء يف الدعــوى وقــرر أنــه يقــوم مقــام أخيــه قائــد الســيارة املباشــرة‬\n ‫للحــادث ‪ -‬قــرر املدعــى عليــه أن التقديــرات الثــاث مبالــغ فيهــا ‪ -‬ملــا‬\n\n                                                                                         ‫‪40‬‬\n\f     ‫قــرره أهــل العلــم مــن أن املتيقــن هــو األقــل يف األروش صــدر احلكــم‬\n     ‫بإلــزام املدعــى عليــه بدفــع أرش تلفيــات ســيارة املدعــى وفــق التقديــر‬\n     ‫األقــل ‪ -‬لــم يقتنــع املدعــى عليــه باحلكــم ‪ -‬صــدق احلكــم مــن محكمــة‬\n     ‫االســتئناف ‪ -‬جــري تســليم املبلــغ احملكــوم بــه وبذلــك انتهــت القضيــة ‪.‬‬\n\n\n\n\n     ‫ـدي‬\n       ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬فلـ َّ‬\n     ‫ـاء علــى املعاملــة الــواردة‬\n                                ‫أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n     ‫إلينــا مــن شــعبة مــرور محافظــة االحســاء بالرقــم ‪2827‬واملقيــدة بهــذه‬\n     ‫احملكمــة برقــم ‪33378975‬وتاريــخ ‪1433/02/27‬ه ـ واحملالــة لنــا مــن‬\n     ‫فضيلــة رئيــس احملكمــة برقم‪33143924‬وتاريخ‪1433/02/27‬ه ـ‬\n     ‫فتحــت اجللســة األولــى يف يــوم الثالثــاء ‪1433/06/24‬ه ـ الســاعة الثامنة‬\n     ‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)...‬‬\n     ‫وا َّدعــى علــى احلاضــر معــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫ا يف دعــواه ‪ :‬إننــي كنـ ُـت أســير بســيارتي بالقــرب مــن‬      ‫رقــم ‪ ...‬قائ ـ ً‬\n     ‫دوار ‪ ...‬وجــاء أخ املدعــى عليــه ‪ ...‬واصطــدم بــي مــن اخللــف بســيارة‬\n     ‫أخيــه ممــا أدى إلــى حصــول تلفيــات بســيارتي قــدرت ثــاث تقديــرات‬\n     ‫األول قبــل احلــادث بتســعة وعشــرين ألــف ريــال وبعــد احلــادث بســتة‬\n     ‫وعشــرين ألــف ريــال والفــارق ثالثــة آالف ريــال والتقديــر الثانــي قبــل‬\n     ‫احلــادث بثمانيــة وعشــرين ألــف ريــال وبعــد احلــادث بأربعــة وعشــرين ألــف‬\n     ‫ريــال والفــارق أربعــة آالف ريــال والتقديــر الثالــث قبــل احلــادث بخمســة‬\n     ‫وثالثــن ألــف ريــال وبعــده بواحــدٍ وثالثــن ألــف ريــال والفــارق ثالثــة‬\n     ‫آالف وخمســمائة ريــال وقــد أديــن الســائق بنســبة مائــة باملائــة أطلــب‬\n\n‫‪41‬‬\n\f‫احلكــم علــى املدعــى عليــه بدفــع أرش قيمــة ســيارتي وقــدره ثالثــة آالف‬\n‫وخمســمائة ريــال إضافــة إلــى تســعني ريــا ًال أجــرة تســعير الــورش الثــاث‬\n‫لســيارتي هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي أجــاب‬\n‫ا ‪ :‬مــا ذكــره املدعــي يف دعــواه مــن احلــادث ووقوعــه ونســبة اإلدانــة‬       ‫قائـ ً‬\n‫والتســعيرات وأجــرة الــورش الثــاث كل ذلــك صحيــح لكـ َّـن القائــد‬\n‫ـتعد بدفــع املبلــغ الــذي يحكــم بــه‬\n                                      ‫هــو أخــي ‪ ...‬وأنــا أقــوم مقامــه ومسـ ٌ‬\n‫والســيارة ســيارتي لكـ َّـن التســعيرات مبال ـ ٌغ فيهــا وأطلــب مــن املدعــي‬\n‫تخفيــض هــذا املبلــغ هكــذا أجــاب وبعــرض إجابــة املدعــى عليــه علــى‬\n‫ـتعد بالتنــازل عــن أي مبلــغ وال‬‫ا ‪ :‬إننــي لسـ ُـت مسـ ٌ‬     ‫املدعــي أجــاب قائ ـ ً‬\n‫ـاء علــى مــا تقــدم مــن‬\n                         ‫أريــد الصلــح مــع املدعــى عليــه هكــذا قــرر فبنـ ً‬\n‫أن املدعــى عليــه أقـ َّـر بدعــوى املدعــي وصــادق‬    ‫الدعــوى واإلجابــة ومبــا َّ‬\n‫علــى صحــة وقــوع احلــادث ونســبة إدانــة أخيــه والتزامــه بــأي مبلــغ يلــزم‬\n‫بــه واســتناد ًا إلــى تقريــر املــرور بإدانــة أخــي املدعــى عليــه بنســبة مائــة‬\n‫ـاء علــى قــرار أهــل اخلبــرة بتقييــم ســيارة املدعــي قبــل احلــادث‬ ‫باملائــة وبنـ ً‬\n‫أن املتيقــن هــو األقــل مــن األروش الثالثــة‬\n                                              ‫وبعــده وملــا قــرره أهــل العلــم مــن َّ‬\n‫قــال الســيوطي رحمــه اهلل‪( :‬ويؤخــذ يف الغــرم باألقــل ‪ ،‬ولــه مأخــذان‬\n‫‪ :‬أحدهمــا ‪ -‬وهــو األظهــر ‪ -‬أن األقــل متيقــن ‪ ،‬والزائــد مشــكوك‬\n‫فيــه ‪ ،‬فــا يلــزم بالشــك ‪ .‬والثانــي ‪ -‬أن التــي شــهدت باألقــل ‪ ،‬رمبــا‬\n‫اطلعــت علــى عيــب) لــذا فقــد ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره‬\n‫ـررت عــدم اســتحقاق املدعــي ملــا‬‫ثالثــة آالف وتســعون ريــا ًال للمدعــي وقـ ُ‬\n‫زاد عــن هــذا املبلــغ وبــه حكمـ ُـت وبعــرض احلكــم علــى الطرفــن قــررا‬\n‫عــدم قناعتهمــا باحلكــم وطلبــا متكينهمــا مــن تقــدمي الئحــة اعتراضيــة‬\n‫مت تســليمهما حــا ًال نســخة مــن احلكــم‬      ‫عليــه فأجيبــا إلــى طلبهمــا و َّ‬\n\n\n                                                                                            ‫‪42‬‬\n\f     ‫ـداء مــن هــذا اليــوم وإذا‬\n                               ‫ـأن مــدة االعتــراض ثالثــون يوم ـ ًا ابتـ ً‬‫وأفهمــا بـ َّ‬\n     ‫ـإن حقهمــا يف االســتئناف‬    ‫لــم يقدمــا اعتراضهمــا خــال هــذه املــدة فـ َّ‬\n     ‫يســقط ويكتســب القطعيــة فأبديــا فهمهمــا لذلــك وأقفلــت اجللســة‬\n     ‫الســاعة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه أجمعــن ُحـ ِـر َر يف ‪1433/07/27‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n     ‫يــوم الثالثــاء ‪1433/08/06‬ه ـ فتحــت اجللســة الثالثــة الســاعة الواحــدة‬\n     ‫ـاء علــى الالئحــة املقدمــة مــن ‪ ...‬وقــد قيــدت‬‫وخمســة وأربعــن دقيقــة وبنـ ً‬\n     ‫هــذه الالئحــة باحملكمــة برقم ‪ 33/1454431‬بتاريــخ ‪1433/08/03‬هـ‬\n     ‫واملكونــة مــن صفحــه واحــده وقــد جــرى االطــاع علــى الالئحــة ولــم‬\n     ‫أجــد فيهــا مــا يوجــب الرجــوع عمــا حكمــت بــه وأمــرت برفــع كامــل‬\n     ‫أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وأقفلــت اجللســة‬\n     ‫الســاعة الثانيــة وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪1433/08/06‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي باحملكمــة اجلزئيــة‬\n     ‫باألحســاء ففــي هــذا اليــوم االحــد ‪1434/06/04‬ه ـ فتحــت اجللســة‬\n     ‫الســاعة الثانيــة عشــر والربــع وقــد عــادت إلينــا املعاملــة مــن مديــر‬\n     ‫شــعبة تنفيــذ األحــكام برقــم ‪ 9060‬تاريــخ ‪1434/05/27‬ه ـ واملقيــدة‬\n     ‫باحملكمــة برقــم ‪ 33373975‬واملرفــق بهــا الشــيك رقــم ‪034553‬‬\n     ‫وتاريــخ ‪1434/05/25‬ه ـ املســحوب علــى البنــك ‪ ...‬مببلــغ (‪ 3090‬ريــال)‬\n     ‫وحضــر لــدي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)...‬‬\n     ‫وجــرى تســليمه الشــيك املذكــور أعــاه وعليــه جــرى التوقيــع وأمــرت‬\n     ‫بالتهميــش علــى صكــه مبــا طــرأ عليــه وأقفلــت اجللســة الســاعة الثانيــة‬\n\n\n‫‪43‬‬\n\f‫عشــر والنصــف وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                ‫حــرر يف ‪1434/06/04‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى‬\n‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n‫واملقيــدة لدينــا برقــم ‪34/181824‬‬\n                                 ‫ّ‬     ‫‪ 34/23347‬وتاريــخ ‪1434/1/18‬ه ـ‬\n‫وتاريــخ ‪1434/1/20‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ‪ ... /‬املسـ ّـجل برقــم ‪ ...‬وتاريــخ ‪1433/7/27‬ه ـ اخلــاص‬\n‫بدعــوى‪ ... /‬ضــد‪ ... /‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحتــن االعتراضيتــن وأوراق املعاملــة قررنــا املصادقة على احلكم‬\n‫بعــد اإلجــراء األخيــر ‪ ،‬ولبيانــه جــرى حتريــره يف ‪1434/3/11‬هـ ‪ ،‬واهلل‬\n                                                              ‫ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                  ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":40,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa1d6eec07d080659ef2fcd9395886273a47b63a137203eb96ee4a2a63ebd093","normalized_text_hash":"104b1c845a5be31507c29390768c2ac58659b6568d309b7f519c7c4a5e3f586d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p40-33357527"},{"id":"c8e8346c-ba5a-5f7e-bca5-a04eb8131b7e","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -صدم سيارة من اخللف -مطالبة املدعي بدفع أرش إصابته وإصابة زوجته وتلفيات سيارته -إثبات نسبة اإلدانة مبوجب تقرير املرور -دفع مالك السيارة بعدم قيادته لها وقت احلادث -الدفع بسرقة السيارة املباشرة للحادث -وقوع احلادث قبل إباغ صاحب السيارة عن سرقتها -األصل أن العن اململوكة بيد مالكها -إدانة املدعى عليه بكامل اخلطأ ودفع مقابل ما حلق بالسيارة من نقص وأرش إصابة املدعي وزوجته .","document_number":"33366840","case_number":"33159100","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/4","year":"1434","subject":"حادث مروري -صدم سيارة من اخللف -مطالبة املدعي بدفع أرش إصابته وإصابة زوجته وتلفيات سيارته -إثبات نسبة اإلدانة مبوجب تقرير املرور -دفع مالك السيارة بعدم قيادته لها وقت احلادث -الدفع بسرقة السيارة املباشرة للحادث -وقوع احلادث قبل إباغ صاحب السيارة عن سرقتها -األصل أن العن اململوكة بيد مالكها -إدانة املدعى عليه بكامل اخلطأ ودفع مقابل ما حلق بالسيارة من نقص وأرش إصابة املدعي وزوجته .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/8/4 :‬هـ‬\n                     ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33366840 :‬‬\n                        ‫َر ْق ُم الدعوى‪33159100 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 33366840‬تاريخه‪1433/8/4 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬صــدم ســيارة مــن اخللــف ‪ -‬مطالبــة املدعــي بدفــع‬\n     ‫أرش إصابتــه وإصابــة زوجتــه وتلفيــات ســيارته ‪ -‬إثبــات نســبة اإلدانــة‬\n     ‫مبوجــب تقريــر املــرور ‪ -‬دفــع مالــك الســيارة بعــدم قيادتــه لهــا وقــت‬\n     ‫احلــادث ‪ -‬الدفــع بســرقة الســيارة املباشــرة للحــادث ‪ -‬وقــوع احلــادث‬\n     ‫قبــل إبــاغ صاحــب الســيارة عــن ســرقتها ‪ -‬األصــل أن العــن اململوكــة‬\n     ‫بيــد مالكهــا ‪ -‬إدانــة املدعــى عليــه بكامــل اخلطــأ ودفــع مقابــل مــا حلــق‬\n                          ‫بالســيارة مــن نقــص وأرش إصابــة املدعــي وزوجتــه ‪.‬‬\n\n\n\n\n                                   ‫قاعدة‪ :‬األصل أن العني اململوكة بيد مالكها ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي أصالــة عــن نفســه وبوكالتــه عــن زوجتــه علــى املدعــى‬\n     ‫عليــه بــأن ســيارته تعرضــت للصــدم مــن اخللــف مــن قبــل ســيارة ملكيتهــا‬\n     ‫عائــدة للمدعــى عليــه ‪ -‬انقلبــت ســيارة املدعــي وتعــرض هــو وزوجتــه‬\n     ‫إلصابــات كمــا تعرضــت ســيارته لبعــض التلفيــات ‪ -‬لــم يتمكــن‬\n     ‫املدعــي مــن معرفــة الســائق لهروبــه والنقــاب ســيارة املدعــي ألن الصدم‬\n     ‫كان مــن اخللــف ‪ -‬صــدر تقريــر املــرور بإدانــة املدعــى عليــه بنســبة‬\n     ‫اخلطــأ ‪ - %100‬طلــب املدعــي إلــزام املدعــى عليــه بدفــع أرش إصابتــه‬\n\n‫‪45‬‬\n\f‫وإصابــة زوجتــه وكذلــك أرش تلفيــات ســيارته ‪ -‬أقــر املدعــى عليــه بــأن‬\n‫الســيارة املباشــرة للحــادث ملكيتهــا لــه ‪ -‬دفــع املدعــى عليــه بأنــه لــم‬\n‫يكــن يقــود الســيارة حيــث أن الســيارة قــد ســرقت منــه وقــام بتقــدمي‬\n‫بــاغ بالســرقة ‪ -‬جــرى رجــوع القاضــي إلــى تقريــر املــرور ‪ -‬كمــا جــرى‬\n‫الرجــوع إلــى تقديــر أرش إصابــة املدعــى وزوجتــه وأرش تلفيــات الســيارة‬\n‫‪ -‬حيــث إن احلــادث وقــع بتاريــخ ‪1433/1/13‬ه ـ الســاعة ‪ 12:30‬ظهــر ًا‬\n‫واملدعــى عليــه بلــغ عــن ســرقة ســيارته بنفــس التاريــخ وفــى متــام الســاعة‬\n‫الواحــدة والربــع ظهــر ًا حســب إفــادة املــرور ‪ -‬وحيــث أن األصــل يف‬\n‫العــن اململوكــة بقاؤهــا بيــد مالكهــا لــذا صــدر احلكــم بإدانــة املدعــى‬\n‫عليــه بنســبة اخلطــأ كاملــة حســب تقريــر املــرور واحلكــم عليــه بدفــع‬\n‫أرش إصابــة املدعــي وزوجتــه وكذلــك أرش تلفيــات ســيارته املذكــور‬\n‫قيمــة ذلــك يف منطــوق احلكــم ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‬\n‫‪ -‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف مبالحظــات أهمهــا‬\n‫رفــع البصمــات مــن الســيارة املتســببة يف احلــادث العائــدة للمدعــى عليــه‬\n‫للتأكــد مــن قائدهــا وقــت وقــوع احلــادث ‪ -‬أجــاب فضيلتــه بفــوات محلــه‬\n‫ألن رفــع البصمــات ال بــد أن يكــون خــال املــدة العلميــة وهــى ثمــان‬\n             ‫وأربعــون ســاعة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة بالرياض‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض برقــم ‪ 33159100‬وتاريــخ ‪31433/5‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 33393586‬وتاريــخ ‪1433/2/29‬ه ـ ففــي يــوم الســبت املوافــق‬\n\n                                                                                     ‫‪46‬‬\n\f     ‫‪1433/3/26‬ه ـ افتتحــت اجللســة وحضــر فهيــا ‪ ...‬ســعودي اجلنســية‬\n     ‫مبوجــب ســجل مدنــي رقــم ‪ ...‬وحضــر حلضــوره ‪ ...‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬األول قائــا إنــه بتاريــخ ‪1433/1/13‬ه ـ‬\n     ‫تعرضــت حلــادث تصــادم مــن قبــل ســيارة ميلكهــا املدعــى عليــه مــن نــوع‬\n     ‫كامــري وقــد جنــم عــن هــذا احلــادث إصابتــي وزوجتــي بعــدة كســور‬\n     ‫وتلفيــات بســيارتي قــدرت بأربعــن ألــف ريــال وحيــث إن نســبة اخلطــأ‬\n     ‫يف هــذا احلــادث هــي مائــة باملائــة علــى ســائق الســيارة لــذا اطلــب تقديــر‬\n     ‫أرش إصابتــي وقيمــة الســيارة واحلكــم علــى املدعــى عليــه بتســليمها‬\n     ‫لــي وأنــا لــم أمتكــن مــن معرفــة الســائق ألنــه اصطــدم بــي مــن اخللــف‬\n     ‫وانقلبــت ســيارتي فهــرب بعدهــا فلــم أمتكــن مــن معرفتــه هــذه دعــواي‬\n     ‫وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره املدعــي يف دعــواه ال‬\n     ‫أدري عنــه وال شــان لــي بــه فســيارتي مســروقة وقــد بلغــت عــن ســرقتها‬\n     ‫والبــاغ مرفــق باملعاملــة كمــا أننــي عســكري ومرابــط يف العمــل‬\n     ‫حتــى الســاعة الواحــدة ظهــرا مــن نفــس اليــوم الــذي وقــع فيــه احلــادث‬\n     ‫هكــذا أجــاب وبالرجــوع ألوراق املعاملــة عثــر مــن بينهــا علــى تقريــر‬\n     ‫حــادث املــرور لفــة رقــم ( ) وباالطــاع عليــه وجدتــه يتضمــن أن نســبة‬\n     ‫اخلطــأ يف هــذا احلــادث ترتبــت علــى قائــد الســيارة كاملــة بنســبة ‪%100‬‬\n     ‫كمــا جــرى االطــاع علــي تقديــر قيمــة النقــص الــذي حلــق بســيارة‬\n     ‫املدعــى فتبــن انــه أربعــون ألــف ريــال حــرر يف ‪1433/3/26‬ه ـ ويف‬\n     ‫جلســة أخــرى يــوم األربعــاء املوافــق ‪1433/5/12‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة الثامنــة والنصــف وحضــر فيهــا املدعــي واملدعــى عليــه وابــرز‬\n     ‫لنــا املدعــي التقريريــن الصادريــن مــن مدينــة امللــك عبــد العزيــز الطبيــة‬\n     ‫و مستشــفى امللــك فهــد برقــم ‪ ...‬وتاريــخ ‪1433/4/4‬ه ـ والثانــي برقــم ‪....‬‬\n\n\n‫‪47‬‬\n\f‫وتاريــخ ‪1433/4/5‬ه ـ حــرر يف ‪1433/5/12‬ه ـ ويف جلســة أخــرى يــوم‬\n‫الســبت املوافــق ‪1433/8/3‬ه ـ افتتحــت اجللســة الســاعة الواحــدة ظهــر ًا‬\n‫وحضــر فيهــا طــريف الدعــوى كمــا أحضــر املدعــي وكالــة عــن زوجتــه‬\n‫املصابــة معــه يف نفــس احلــادث مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 3399368‬وتاريــخ ‪1433/6/3‬ه ـ‬\n‫واملتضمنــة املطالبــة وإقامــة الدعــوى واإلقــرار واإلنــكار والتنــازل‬\n‫ا لقــد حصــل احلــادث لــي ولزوجتــي وقــد حلــق بهــا‬ ‫والصلــح وأضــاف قائـ ً‬\n‫إصابــات كثيــرة وهــي تطالــب تســليمها أرش إصاباتهــا وبعرضــه علــى‬\n‫املدعــى عليــه قــال ليــس لــدي ســوى مــا أجبــت بــه ســابق ًا هــذا وقــد وردني‬\n‫خطــاب مــن جلنــة تقديــر الشــجاج باحملكمــة رقــم ‪ 33393586‬وتاريــخ‬\n‫ا فقــد اجتمعــت جلنــة مقــدري الشــجاج‬      ‫‪1433/6/23‬ه ـ ونصــه كام ـ ً‬\n‫باحملكمــة العامــة بالريــاض وأطلعــت علــى املعاملــة رقــم ‪33393586‬‬\n‫وتاريــخ ‪1433/5/15‬ه ـ الــواردة مــن فضيلتكــم واملتضمنــة طلــب‬\n‫تقديــر إصابــة‪ .../‬وبعــد االطــاع علــى املعاملــة ومراجعــة التقريــر الطبــي‬\n‫ومبشــاهدة املصــاب ‪ ...‬تبــن أنــه أصيــب بحــرق احتكاكــي بالطــرف‬\n‫الســفلي األيســر قدرنــاه باثنــي عشــر ألــف ريــال (‪)12000‬حكومــة‪،‬‬\n‫وخــدوش باليــد اليســرى قدرنــا كل خــدش بألــف وخمســمائة ريــال‬\n‫(‪ )1500‬حكومــة‪ ،‬وال نعلــم عددهــا ‪ ،‬وجــرح قطعــي بالكــوع األيســر‬\n‫قدرناه بســتة آالف ريال (‪ )6000‬حكومة‪ ،‬وســحبات بالســاق اليســرى‬\n‫مــع فقــدان للجلــد قدرنــا كل ســحبة بألــف وخمســمائة ريــال (‪)1500‬‬\n‫حكومــة وال نعلــم عددهــا وقدرنــا فقــدان اجللــد بتســعة آالف ريــال‬\n‫(‪ )9000‬حكومــة‪ ،‬أمــا املصابــة ‪ ...‬وبــدون مشــاهدتها فقــد تبــن وجــود‬\n‫آالم بالضلــوع علــى اجلهــة اليســرى األماميــة أســفل الثــدي ناجتــة عــن‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫رضــه قدرناهــا بســتة آالف ريــال (‪ )6000‬حكومــة وآالم أســفل الظهــر‬\n     ‫نتيجــة رضــه قدرناهــا بأربعــة أالف وخمســمائة ريــال (‪ )4500‬حكومــة‬\n     ‫‪ ،‬وكدمــات بالظهــر والكتــف األيســر والفخــذ األيســر والســاق‬\n     ‫قدرنــا كل كدمــة بألــف وخمســمائة ريــال (‪ )1500‬حكومــة واجلميــع‬\n     ‫بأربعــة آالف وخمســمائة ريــال (‪ )4500‬حكومــة ورض علــى الصــدر‬\n     ‫والبطــن قدرنــاه بثالثــة آالف ريــال (‪ )3000‬حكومــة واهلل املوفــق أ‪.‬ه ـ‬\n     ‫وبعرضــه علــى املدعــي أصالــة ووكالــة قــال وموكلتــي نكتفــي مبــا‬\n     ‫ورد يف التقريــر وال نرغــب يف الكتابــة لبيــان عــدد الســحبات واخلــدوش‬\n     ‫هكــذا أقــر وباالطــاع علــى خطــاب مديــر إدارة املــرور بالريــاض رقــم‬\n                                           ‫‪ 925/31/2/7‬وتاريــخ ‪1433/2/24‬ه ـ‬\n     ‫املتضمــن أن تاريــخ بــاغ الهــروب يف يــوم ‪1433/1/13‬ه ـ الســاعة‬\n     ‫الواحــدة والربــع ظهــر ًا ومبطابقتــه مــع تقريــر املــرور املرفــق لفــة ‪ 1‬تبــن‬\n     ‫أن احلــادث وقــع يف يــوم ‪1433/1/13‬ه ـ الســاعة ‪12:30‬الثانيــة عشــر‬\n     ‫والنصــف ظهــر ًا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n     ‫احلــادث وقــع قبــل بــاغ املدعــى عليــه بالســرقة وألن األصــل أن أمــاك‬\n     ‫النــاس تكــون حتــت أيديهــم ومبــا أن الشــرطة واملــرور لــم يثبتــوا أن‬\n     ‫الســيارة كانــت بيــد أخــرى مــن خــال وســائل اإلثبــات كالبصمــات‬\n     ‫لــذا فقــد حكمــت علــى املدعــى عليــه بتســليم املدعــي ســبعون ألــف‬\n     ‫ريــال ‪ ،‬أربعــون ألــف ريــال منهــا لقــاء مــا حلــق بســيارته مــن نقــص وثالثــون‬\n     ‫ألــف ريــال مقابــل أروش اإلصابــات التــي حلقــت بــه كمــا حكمــت علــى‬\n     ‫املدعــى عليــه بتســليم املدعيــة ‪ ...‬ثمانيــة عشــر ألــف ريــال لقــاء مــا حلــق‬\n     ‫بهــا مــن إصابــات وبعرضــه علــى اجلميــع قــرر املدعــي أصالــة ووكالــة‬\n     ‫القناعــة كمــا قــرر املدعــى عليــه عدمهــا وطلــب االســتئناف بالئحــة‬\n\n\n‫‪49‬‬\n\f‫فأجبتــه لطلبــة وجــرى تزويــده بصــورة مــن صــك احلكــم وجــرى إفهامــه‬\n‫بــأن إذا لــم يقــدم الئحتــه خــال ثالثــن يومـ ًا مــن تاريــخ اليــوم فــإن حقــه‬\n‫يف االســتئناف ســاقط واحلكــم نافــذ ففهــم ذلــك‪ .‬وبــاهلل التوفيــق حــرر‬\n                                                                  ‫يف ‪1433/8/3‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/03/18‬ه ـ‬\n‫ويف متــام الســاعة الواحــدة افتتحــت اجللســة وقــد وردنــي قــرار محكمــة‬\n‫االســتئناف رقــم ‪ 3436090‬وتاريــخ ‪1434/02/12‬ه ـ ونصــه وبدراســة‬\n‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ‬\n‫مايلــي ‪ -1‬إجابــة املدعــى عليــه مشــمولة بأنــه كان مرابط ـ ًا يف عملــه‬\n‫حتــى الواحــدة ظهــر ًا مــن ذلــك اليــوم الــذي وقــع احلــادث ثــم علــم بســرقة‬\n‫ســيارته وبحــث عنهــا ثــم تقــدم ببــاغ ســرقة واملتعــن علــى فضيلتــه‬\n‫التأكــد مــن صحــة ذلــك عــن طريــق الكتابــة إلــى عمــل املدعــى عليــه‬\n‫لتحديــد عملــه وخروجــه يــوم احلــادث محــل الدعــوى وتقريــر مــا يظهــر لــه‬\n‫‪ -2‬لــم يصــرح فضيلتــه مبوجــب إدانــة قائــد الســيارة األخــرى بواقــع مائــة‬\n‫باملائــة كمــا لــم يصــرح مبوجــب نقــص قيمــة ســيارة املدعــي ومصــدره‬\n‫والبــد مــن ذلــك ‪ -3‬لــم يطلــع فضيلتــه علــى اســتمارة ملكيــة ســيارة‬\n‫املدعــي واملدعــى عليــه وتدويــن مضمونهــا ‪ -4‬يتوجــه مناقشــة املدعــى‬\n‫عليــه عــن مضمــون تقريــر املــرور ونســبة اإلدانــة وتدويــن القناعــة مــن‬\n‫عدمهــا ‪ -5‬تضمــن خطــاب ســعادة مديــر مــرور الريــاض املرفــق باملعاملــة‬\n‫وطلبــه مــن ســعادة مديــر شــرطة املعــذر تكليــف فنــي لديهــم باالنتقــال‬\n‫إلــى الســيارة باحلجــز وتصويرهــا ورفــع مــا عليهــا مــن اثــر يفيد الكشــف‬\n‫عــن هويــة الســائق واملتوجــه اطــاع فضيلتــه علــى هــذا اخلطــاب والرفــع‬\n‫إلــى اجلهــة املختصــة ملطابقــة بصمــة املدعــى عليــه علــى ذلــك األثــر أن‬\n\n\n                                                                                        ‫‪50‬‬\n\f     ‫وجــد ‪ -6‬اســتدالل فضيلتــه بــأن األصــل أن العــن اململوكة بيد مالكها‬\n     ‫يتعقــب عليــه أن املدعــى عليــه دفــع خــاف ذلــك ولــم يطلــب منــه إثبــات‬\n     ‫فعلــى فضيلتــه بيــان مســتنده الشــرعي يف هــذا احلكــم واهلل املوفــق‬\n     ‫عليــه أجيــب أصحــاب الفضيلــة حفظهــم اهلل مبــا يلــي أو ًال ‪ :‬إجابــة علــى‬\n     ‫ماذكــر يف أو ًال وسادسـ ًا فــإن أصحــاب الفضيلــة حفظهــم اهلل لــو تأملــوا‬\n     ‫الســاعة التــي وقــع فيهــا احلــادث لوجــدوا أنهــا كانــت يف متــام الســاعة‬\n     ‫الثانيــة عشــرة والنصــف بتاريــخ ‪1433/01/13‬ه ـ وتبليــغ املدعــى عليــه‬\n     ‫كان يف متام الســاعة الواحدة والربع ظهر ًا يف ‪1433/01/13‬هـ حســب‬\n     ‫إفــادة مديــر مــرور منطقــة الريــاض املرفقــة باملعاملــة وليلحــظ أصحــاب‬\n     ‫الفضيلــة أن التبليــغ لــم يكــن بعــد نهايــة الــدوام الرســمي فكيــف علــم‬\n     ‫املدعــى عليــه بالســرقة وهــو يزعــم أنــه يف دوامــه ولــو قبــل هــذا لــكان‬\n     ‫لــكل أحــد أن يفعــل الشــيء ذاتــه ليســلم مــن تبعــات أفعالــه ويزعــم أن‬\n     ‫الســيارة قــد ســرقت ثانيـ ًا ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بنســبة احلــادث‬\n     ‫وقدرهــا مائــة باملائــة ثالث ـ ًا ‪ :‬أمــا اســتمارة الســيارة فقــد جــرى االطــاع‬\n     ‫عليهــا ومطبوعاتهــا مرفقــة باملعاملــة مــن اجلهــة الرســمية رابع ـ ًا ‪ :‬وأمــا‬\n     ‫النســبة املقــررة يف تقريــر املــرور فقــد ســبق أن عرضتهــا علــى املدعــى‬\n     ‫عليــه واعتــرض عليهــا وأمــا مــا ذكــر مــن البصمــة فمحلــه قــد فــات ألن‬\n     ‫الواجــب هــو رفعهــا خــال املــدة العلميــة لهــا وهــي ثمانيــة وأربعــون ســاعة‬\n     ‫لــذا فإنــي علــى مــا حكمــت بــه ورفعــت اجللســة يف متــام الســاعة الواحــدة‬\n     ‫والنصــف وبــاهلل التوفيــق ؛ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                     ‫إلــه وصحبــة وســلم ‪ .‬حــرر يف ‪1434/03/11‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n     ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n\n\n‫‪51‬‬\n\f‫الــواردة مــن فضيلــة رئيس احملكمة العامة بالرياض برقم‪34/749270‬‬\n‫وتاريــخ ‪1434/6/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪ ...‬وتاريخ‪1433/8/4‬ه ـ اخلــاص‬\n‫بدعــوى ‪ ...‬ضــد ‪ ...‬يف قضيــة حــادث مــروري علــى النحــو املوضــح بالصــك‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه ‪ .‬حيــث ســبق‬\n‫دراســة الصــك وصــورة ضبطــه والئحــة وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي واحلقــه بالصــك وصــورة ضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪34200889‬وتاريــخ ‪1434/4/29‬ه ـ لــم يظهــر لألكثريــة‬\n‫مــا يوجــب املالحظــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪52‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":45,"source_page_end":52,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"29d183bbb9fe99b9fe6defad2c4ea13c14ea133ce3078dd2c5dc7cb1fa040316","normalized_text_hash":"5c403880db6ac00899f991c12c20c8e9eafca4e7617e2bc223beb589ed675af6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p45-33366840"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6d1c2ecf-addc-5da8-a2b4-a406d549530f","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -تصادم سيارتني -مطالبة بأرش تلفيات سيارة - تقدير أرش تلفيات سيارة من قبل أهل اخلبرة -حكم بشاهد ومين -إلزام املدعى عليه بدفع أرش تلفيات سيارة املدعي -إقرار باستالم املبلغ احملكوم به .","document_number":"3418933","case_number":"33611693","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة باملصادقة على احلكم -حضر املدعي وقرر استالمه للمبلغ احملكوم به","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"حادث مروري -تصادم سيارتني -مطالبة بأرش تلفيات سيارة - تقدير أرش تلفيات سيارة من قبل أهل اخلبرة -حكم بشاهد ومين -إلزام املدعى عليه بدفع أرش تلفيات سيارة املدعي -إقرار باستالم املبلغ احملكوم به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/21 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3418933 :‬‬\n                        ‫َر ْق ُم الدعوى‪33611693 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34203062‬تاريخه‪1434/5/1 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬تصــادم ســيارتني ‪ -‬مطالبــة بــأرش تلفيــات ســيارة ‪-‬‬\n     ‫تقديــر أرش تلفيــات ســيارة مــن قبــل أهــل اخلبــرة ‪ -‬حكــم بشــاهد وميــن‬\n     ‫‪ -‬إلــزام املدعــى عليــه بدفــع أرش تلفيــات ســيارة املدعــي ‪ -‬إقــرار باســتالم‬\n                                                                ‫املبلــغ احملكــوم بــه ‪.‬‬\n\n\n\n                            ‫قضاء النبي صلى اهلل عليه وسلم بالشاهد واليمني‬\n\n\n\n\n     ‫ادعــى املدعــي بــأن املدعــى عليــه تســبب يف تلفيــات حلقــت بســيارة‬\n     ‫املدعــي جــراء حــادث مــروري وأديــن املدعــى عليــه بنســبة اخلطــأ ‪%100‬‬\n     ‫وطالــب باحلكــم علــى املدعــى عليــه بــأرش تلفيــات الســيارة ‪ -‬أجــاب‬\n     ‫املدعــى عليــه بــأن املتســبب يف احلــادث هــو املدعــي وطالــب بــأرش تلفيات‬\n     ‫ســيارته ‪ -‬أحضــر املدعــي شــاهد ًا واحــد ًا تضمنــت شــهادته صحــة دعوى‬\n     ‫املدعــي و ُعـ ِّـدلَ الشــاهد ‪ -‬قــرر املدعــى عليــه أن شــهادة الشــاهد غيــر‬\n     ‫صحيحــة وان الشــاهد ال يعلــم عنــه شــيئ ًا ‪ -‬افهــم ناظــر القضيــة املدعــي‬\n     ‫بــأن عليــه بــذل اليمــن علــى صحــة دعــواه وحلــف علــى ذلــك ‪ -‬مت تقديــر‬\n     ‫أرش تلفيــات ســيارة املدعــي مــن قبــل أهــل اخلبــرة صــدر احلكــم بإلــزام‬\n     ‫املدعــى عليــه بتســليم األرش للمدعــي ‪ -‬قــرر املدعــي القناعــة وقــرر‬\n\n‫‪15‬‬\n\f‫املدعــى عليــه عــدم القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف مبكــة‬\n‫املكرمــة باملصادقــة علــى احلكــم ‪ -‬حضــر املدعــي وقــرر اســتالمه‬\n                                                 ‫للمبلــغ احملكــوم بــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا مســاعد رئيــس احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 33611693‬وتاريــخ‬\n‫‪1433/10/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331843913‬وتاريــخ‬\n‫‪ 1433/10/18‬هـ ففي ي ـ ــوم الثالثاء املوافق‪1433/11/09‬هـ افتتحت‬\n‫اجللســة الــساعـ ـ ــة ‪ 10: 15‬وفيهــا حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .....‬وأدعــى علــى احلاضــر معــه ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم قائــا يف دعــواه عليــه تســبب املدعــى عليــه‬\n‫يف تلفيــات حلقــت بســيارتي جــراء حــادث مــروري أديــن فيــه بنســبة مائــة‬\n‫باملائــة أطلــب احلكــم عليــه بــأرش تلفيــات ســيارتي هــذه دعواي وبســؤال‬\n‫املدعــى عليــه قــال مــا ادعــاه املدعــي غيــر صحيــح والصحيــح أن املدعــي‬\n‫هــو املتســبب يف احلــادث وأطلبــه أرش تلفيــات ســيارتي فســألت املدعــي‬\n‫وصــف احلــادث فقــال أن املدعــى عليــه جتــاوز بســيارته اجليــب ســيارتي‬\n‫الكامــري مــن اليمــن وتفاجــأ بصاحــب حافلــة يف وجهــه فانحــرف‬\n‫بســيارته علــى ســيارتي فأتلــف االســطب األمامــي األميــن وشــيئا مــن‬\n‫الصــدام والكبــوت والشــمعة وبعــرض ذلــك علــى املدعــى عليــه قــال ال‬\n‫صحــة ملــا ادعــاه املدعــي فســألت املدعــي البينــة فقــال أطلــب امهالــي‬\n‫ويف يــوم اإلثنــن املوافــق‪ 1433/12/27‬ه ـ افتتحــت اجللســة الســاعة (‬\n\n                                                                                 ‫‪16‬‬\n\f     ‫‪ ) 9 : 00‬وفيهــا حضــر الطرفــان وجــرى ســؤال املدعــى عليــه عــن وصــف‬\n     ‫احلــادث فقــال كنــت أســير يف شــارع ‪........‬بعــد قاعــة ‪........‬وكنــت‬\n     ‫أســير يف املســار األيســر وتفاجــأت باملدعــي يقــود ســيارته الكامــري‬\n     ‫بعــد اخلــط األصفــر وصدمنــي مــن اجلهــة اليســرى وتزحلقــت ســيارتي‬\n     ‫مــن قــوة االصطــدام وصدمــت يف الصبــات وانكســر الكفــر األمامــي‬\n     ‫وتدحــرج حتــى دخــل يف الشــارع الثانــي فطلبــت مــن املدعــي البينــة‬\n     ‫فأحضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم مــن مواليــد‬\n     ‫عــام ‪1401‬ه ـ ويســكن مكــة فســألته عــن عالقتــه باملدعــي فقــال ال‬\n     ‫تربطنــي بــه عالقــة ســوى رابطــة الديــن وباستشــهاده شــهد هلل قائــا‬\n     ‫كنــت أســير يف طريقــي وجتاوزنــي ســيارتني الكامــري يف املقدمــة‬\n     ‫واجليــب خلفــه مباشــرة وكانــا يســيران بســرعة جنونيــة وعنــد وصولــي‬\n     ‫إلــى املنعطــف رأيــت كلتــا الســيارتني اجليــب يف اليمــن والكامــري يف‬\n     ‫اليســار قــد وقــع بينهمــا حــادث اصطــدام ولــم أرهمــا حلظــة االصطــدام‬\n     ‫فنزلــت وســألت املدعــى عليــه صاحــب اجليــب كيــف وقــع احلــادث فقــال‬\n     ‫كنــت خلــف صاحــب الكامــري ويقصــد املدعــي وحاولــت جتــاوزه‬\n     ‫باالنحــراف مــن جهــة اليمــن إال أننــي تفاجــأت بصاحــب احلافلــة يف‬\n     ‫وجهــي فاضطــررت إلــى االنحــراف علــى الكامــري حتــى ال اصطــدم‬\n     ‫باحلافلــة وانحرفــت جهــة اليســار وصدمــت الكامــري ثــم انحرفــت جهــة‬\n     ‫احلافلــة وصدمتهــا هــذا مــا لــدي مــن شــهادة وبعــرض حــال الشــاهد ومــا‬\n     ‫جــاء يف شــهادته علــى املدعــى عليــه قــال أمــا حالــه فــا أعلــم عنــه شــيئا‬\n     ‫وأمــا مــا جــاء يف شــهادته فشــهادته غيــر صحيحــة فســألت املدعــي هــل‬\n     ‫لديــك زيــادة بينــة فقــال ليــس لــدي ســوى مــن أحضــرت فطلبــت مــن‬\n     ‫املدعــى عليــه البينــة علــى مــا ادعــاه مــن وصــف احلــادث فقــال ليــس لــدي‬\n\n\n‫‪17‬‬\n\f‫بينــة فطلبــت م ـ ــن املدعــي تزكي ــة شــاهـ ــده فاستعـ ـ ــد بذلــك ويف ي ـ ـ ـ ــوم‬\n‫اإلثنني املواف ـ ــق‪1434/01/12‬هـ افتتحت اجللـ ـ ـس ــة الساعـ ـ ــة ( ‪) 9 : 30‬‬\n‫وفيهــا حضــر الطرفــان وأحضــر املدعــي معــه ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم و ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫وباستشــهادهما شــهدا بعدالــة وثقــة الشــاهد املذكــور أعــاه عليــه‬\n‫أفهمــت املدعــي بــأن عليــه بــذل اليمــن بــأن املدعــى عليــه انحــرف‬\n‫بســيارته جهــة اجلانــب األميــن مــن ســيارته وأن املدعــى عليــه هــو مــن‬\n‫صدمــه يف اجلانــب األميــن مــن ســيارته وأن وصــف املدعــى عليــه للحــادث‬\n‫غيــر صحيــح فحلــف قائــا واهلل العظيــم أن املدعــى عليــه انحــرف‬\n‫بســيارته علــى ســيارتي مــن اجلانــب األميــن واصطــدم بهــا وأن وصــف‬\n‫املدعــى عليــه للحــادث غيــر صحيــح فجــرى االطــاع علــى تقديــر شــيخ‬\n‫املعــارض املرفــق باملعاملــة لفــه (‪ )19‬وجــاء فيــه تقديــر ســيارة املدعــي‬\n‫قبــل احلــادث ( ‪ )26000‬وبعــده (‪ )24200‬وبنــاء علــى مــا تقــدم وشــهادة‬\n‫الشــاهد وميــن املدعــي وحيــث ال بينــة للمدعــى عليــه علــى دعــواه‬\n‫ولقضــاء النبــي صلــى اهلل عليــه وســلم بالشــاهد واليمــن فقــد حكمــت‬\n‫علــى املدعــى عليــه بدفــع ألــف وثمامنائــة ريــال (‪ )1800‬للمدعــي وبعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــي قناعتــه باحلكــم كمــا قــرر املدعــى‬\n‫عليــه االعتــراض وطلــب محكمــة االســتئناف فأجبتــه لطلبــه وأفهمتــه‬\n‫بــأن مــدة االعتــراض ثالثــون يومــا تبــدأ مــن يــوم الســبت ‪1434/1/17‬ه ـ‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪ 1434/01/12‬ه ـ‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/04/16‬ه ـ افتتحت اجللســة الســاعة (‪30‬‬\n‫‪ )10 :‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n\n\n                                                                                            ‫‪18‬‬\n\f     ‫بالرقــم ‪ 34525469‬يف ‪1434/3/11‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة‬\n     ‫األولــى رقــم ‪ 3456552‬يف ‪1434/3/7‬ه ـ املتضمــن ودراســة احلكــم‬\n     ‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا إعادتهــا لفضيلــة حاكــم‬\n     ‫القضيــة ملالحظــة أن الشــاهد ذكــر يف شــهادته أن املدعــي واملدعــى‬\n     ‫عليــه كانــا يســيران بســرعة جنونيــة وهــذا يعنــي أنهمــا يتحمــان ســويا‬\n     ‫مســؤولية احلــادث كمــا أن مــن أعــد تقريــر احلــادث ذكــر يف تقريــره‬\n     ‫أن نســبة اخلطــأ علــى الطرفــن بنســبة خمســن باملائــة علــى كل واحــد‬\n     ‫منهمــا فعلــى فضيلتــه إعــادة النظــر والتأمــل وعــرض الصلــح علــى‬\n     ‫الطرفــن وإجــراء مــا يلــزم واهلل املوفــق واجلــواب عليــه ذكــر أصحــاب‬\n     ‫الفضيلــة أن معــد تقريــر احلــادث ذكــر يف تقريــره أن نســبة اخلطــأ علــى‬\n     ‫الطرفــن بنســبة خمســن باملائــة علــى كل واحــد منهمــا والصحيــح‬\n     ‫أن محضــر نســبة اإلدانــة املرفــق باملعاملــة لفــه (‪ )31‬قــد وضــع النســبة‬\n     ‫كاملــة علــى املدعــى عليــه أمــا مــا ذكــره الشــاهد وهــوا أنهمــا كانــا‬\n     ‫يســيران بســرعة جنونيــة فهــذا حــن جتــاوزه املتداعيــان بســيارتهما ثــم‬\n     ‫غابــا عنــه ثــم لــو فــرض أن املدعــي كان يســير بســرعة فليســت الســرعة‬\n     ‫ســببا يف احلــادث وإمنــا الســبب هــوا انحــراف املدعــى عليــه اخلاطــئ ولــذا‬\n     ‫فلــم يظهــر لــي مــا يوجــب إعــادة النظــر فيمــا حكمــت بــه وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                 ‫‪ 1434/04/16‬هــ‪.‬‬\n     ‫ويف يــوم الثالثــاء املوافــق‪ 1435/01/23‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫(‪ )10 : 00‬وفيهــا حضــر املدعــي وقــرر اســتالمه كامــل املبلــغ احملكــوم‬\n     ‫بــه لــذا جــرى إثبــات ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1435/01/23‬ه ـ‬\n\n\n‫‪19‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34833377‬وتاريــخ‬\n‫‪ 1434/4/22‬هـ ـ املرفــق بهــا الصــك الشــرعي رقــم ‪ 3418933‬وتاريــخ‬\n‫‪ 1434/1/21‬هـ ـ الصــادر مــن فضيلــة الشــيخ ‪ /‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى ضــد ‪ /‬املتهــم بقضيــة‬\n                            ‫حــادث مــروري احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪20‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":15,"source_page_end":20,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ed77fd932c8f66d894d207b858cf4d431455b51ecc799191d28faeb1f4e58151","normalized_text_hash":"f72b299c90fdbb7adc959d39be5373bcd4c5ffe90f61b5c0c69608b6f7551a87","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p15-3418933"},{"id":"ec7a4672-6155-59c9-9810-bdbcfcbe92c8","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -أخذ سيارة بدون علم صاحبها والصدم بها -تقدير قيمة تلفيات السيارة -إثبات اإلدانة باإلقرار -اإللزام بدفع قيمة","document_number":"3422357","case_number":"3429721","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة عيون اجلواء املنتدب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/25","year":"1434","subject":"حادث مروري -أخذ سيارة بدون علم صاحبها والصدم بها -تقدير قيمة تلفيات السيارة -إثبات اإلدانة باإلقرار -اإللزام بدفع قيمة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/1/25 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3422357 :‬‬\n                        ‫َر ْق ُم الدعوى‪3429721 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪34183747‬تاريخه‪1434/4/9 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬أخــذ ســيارة بــدون علــم صاحبهــا والصــدم بهــا ‪ -‬تقديــر‬\n     ‫قيمــة تلفيــات الســيارة ‪ -‬إثبــات اإلدانــة باإلقــرار‪ -‬اإللــزام بدفــع قيمــة‬\n                                                                       ‫األرش األقــل‪.‬‬\n\n\n\n\n                                                               ‫‪ -1‬قاعدة ‪:‬ال عذر ملن أقر ‪.‬‬\n                                                     ‫‪ -2‬قاعدة ‪ :‬اإلقرار حجه على املقر ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بأخــذ مفتــاح ســيارته مــن دون‬\n     ‫علمــه أثنــاء تواجدهمــا يف اســتراحة ‪ -‬انقلــب املدعــى عليــه بالســيارة يف‬\n     ‫الطريــق العــام ‪ -‬مت تقديــر أرش التلفيــات مــن قبــل معرضــن للســيارات‬\n     ‫‪ -‬طلــب املدعــي إلــزام املدعــى عليــه بدفــع األرش ‪ -‬أقــر املدعــى عليــه‬\n     ‫مبــا جــاء يف دعــوى املدعــي ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع‬\n     ‫األرش األقــل ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪21‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة العامــة مبحافظــة‬\n‫عيــون اجلــواء املنتــدب وبنــاء على املعاملــة املقيدة لدينا برقم ‪34143796‬‬\n‫وتاريــخ ‪1434/1/18‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/01/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــى علــى احلاضــر معــه ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬قائــا يف دعــواه عليــه لقــد قــام‬\n‫املدعــى عليــه بأخــذ مفتــاح ســيارتي نــوع ‪ ....‬لوحــة رقــم (‪ )...‬دون علمــي‬\n‫حيــث كنــت أنــا وإيــاه يف اســتراحة يف منطقــة حائــل وقــام بالذهــاب‬\n‫بالســيارة إلــى جهــة ال أعلمهــا وأخبرنــي أحــد زمالئــي أن ســيارتي‬\n‫املذكــورة أعــاه منقلبــة قريبــا مــن االســتراحة علــى شــارع عــام وذهبــت‬\n‫إلــى ســيارتي ووجــدت املــرور عندهــا وأنــا ال أعــرف مــن قــام بهــذا العمــل‬\n‫حينهــا ثــم ســألت رجــل املــرور أيــن قائــد الســيارة فقــال لــي يف مستشــفى‬\n‫امللــك خالــد يف حائــل وعندمــا ذهبــت وجــدت أنــه زميلــي املدعــى عليــه‬\n‫وكمــا أســلفت فقــد أخــذ املفتــاح دون علمــي حيــث إننــي وضعــت‬\n‫املفتــاح حتــت الفــراش يف االســتراحة وقــد قــدرت الســيارة قبــل وبعــد‬\n‫احلــادث مــن معــرض ‪ ...‬مبوجــب اخلطــاب املرفــق باملعاملــة لفــة رقــم (‪)8‬‬\n‫قبــل احلــادث مبلــغ وقــدره ســتون ألــف ريــال وبعــد احلــادث مببلــغ وقــدره‬\n‫خمســة عشــر ألــف ريــال ليصبــح الفــارق بــن القيمتــن مبلــغ وقــدره‬\n‫خمســة وأربعــون ألــف ريــال كمــا قــدرت مــن معــرض ‪ ...‬للســيارات‬\n‫حســب اللفــة رقــم (‪ )7‬املرفقــة باملعاملــة قبــل احلــادث مببلــغ وقــدره ســتون‬\n‫ألــف ريــال وبعــد احلــادث مببلــغ وقــدره خمســة عشــر ألــف ريــال والفــرق‬\n\n                                                                                      ‫‪22‬‬\n\f     ‫بــن القيمتــن هــو مبلــغ وقــدره خمســة وأربعــون ألــف ريــال لذلــك كلــه‬\n     ‫أطلــب إلــزام املدعــى عليــه بتســليمي الفــرق بــن القيمتــن وهــو مبلــغ‬\n     ‫وقــدره خمســة وأربعــون ألــف ريــال حــا ًال هــذه دعــواي وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي يف دعــواه كلــه صحيــح‬\n     ‫جملــة وتفصيــا وقــد أخــذت الســيارة دون علــم املدعــي مــن ابــن عمــه‬\n     ‫وحصــل احلــادث وأنــا املتســبب يف هــذا احلــادث هكــذا أجــاب ثــم جــرى‬\n     ‫منــي االطــاع علــى أوراق املعاملــة فوجــدت بــن طياتهــا تقاريــر ســيارة‬\n     ‫املدعــي طبق ـ ًا ملــا ذكــره املدعــي فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وحيــث أقــر وصــادق املدعــى عليــه علــى دعــوى املدعــي جملــة‬\n     ‫ا وحيــث إنــه ال عــذر ملــن أقــر وحيــث إن اإلقــرار حجــة علــى‬      ‫وتفصي ـ ً‬\n     ‫املقــر لذلــك كلــه فقــد ثبــت لــدي أن املدعــى عليــه ‪ ...‬هــو املتســبب يف‬\n     ‫انقــاب ســيارة املدعــي املذكــورة يف الدعــوى حســب إقــراره وألزمتــه‬\n     ‫بتســليم املدعــي املبلــغ املدعــى بــه حــاال وقــدره خمســة وأربعــون ألــف ريال‬\n     ‫وبذلــك حكمــت وقضيــت وبعرضــه عليهمــا قــرر املدعــى القناعــة بــه‬\n     ‫أمــا املدعــى عليــه فقــرر عــدم القناعــة بــه وقــرر أنــه ســوف يقــدم ال ئحــة‬\n     ‫اعتراضيــة علــى احلكــم فأفهمتــه بــأن عليــه التقــدم للمحكمــة خــال‬\n     ‫عشــرة أيــام الســتالم نســخة مــن صــك احلكــم لالعتــراض عليــه خــال‬\n     ‫ثالثــن يومـ ًا مــن تاريــخ تســجيل الصــك وإن لــم يتقــدم باعتراضــه خــال‬\n     ‫هــذه املــدة النظاميــة فــإن حقــه يف اســتئناف احلكــم يســقط ويكتســب‬\n     ‫احلكــم القطعيــة ففهــم ذلــك وعلــى ذلــك جــرى التوقيــع وأقفلــت اجللســة‬\n     ‫متــام الســاعة التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/24‬ه ـ‬\n     ‫احلم ــد هلل وح ــده وبعـد‪...‬فق ــد اطَّ لعنــا نحــن قضــاة الدائــرة الثانية لتدقيق‬\n\n\n‫‪23‬‬\n\f‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة‬\n‫الــواردة مــن فضيلــة قاضــي احملكمــة العامــة مبحافظــة عيــون اجلــواء‬\n‫املنتــدب الشــيخ‪ ... /‬برقــم (‪ )34143796‬يف ‪1434/4/1‬هــ؛ املرفــق‬\n‫بـ ـ ـ ـ ـ ــها الصــك رق ـ ـ ـ ـ ـ ـ ــم (‪ )3422357‬يف ‪1434/1/25‬هــ؛ الصــادر مــن‬\n‫فضيلتــه؛ اخلــاص بدعــوى ‪ .....‬ضــد‪... /‬؛ بشــأن طلــب املدعــي إلــزام‬\n‫املدعــى عليــه بدفــع قيمــة تلفيــات ســيارته‪ ،‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه؛ علــى املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املدعــى بــه وقــدره‬\n‫املفصــل فيــه‪ ،‬وبدراســة الصــك‬  ‫َّ‬  ‫خمســة وأربعــون ألــف ريــال؛ علــى النحــو‬\n‫وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة علــى مــا‬\n‫حكــم بــه فضيلتــه‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪24‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":21,"source_page_end":24,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cba94a24d30b0abd20c35dc7744b8abad750cd531cb0092dc16fe24abb5376cb","normalized_text_hash":"04a4326d0e6473087d6e21ebbdd4ff8ca9504707b63607c42b62bfcc83db1514","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p21-3422357"},{"id":"71836aa1-7171-5e09-90b7-e3671ae74daa","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -تصادم سيارتني -مطالبة بأرش متلف (سيارة) - تصحيح الدعوى على الكفيل احلضوري -االستناد على قرار أهل اخلبرة (تقدير شيخ املعارض) -تضمن الكفيل احلضوري لعجزه عن إحضار مكفوله -إلزام املدعى عليه (الكفيل) بأرش تلف السيارة املقدر من أهل اخلبرة واعتبار احلكم حضوري ا .","document_number":"33480821","case_number":"32590589","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/28","year":"1434","subject":"حادث مروري -تصادم سيارتني -مطالبة بأرش متلف (سيارة) - تصحيح الدعوى على الكفيل احلضوري -االستناد على قرار أهل اخلبرة (تقدير شيخ املعارض) -تضمن الكفيل احلضوري لعجزه عن إحضار مكفوله -إلزام املدعى عليه (الكفيل) بأرش تلف السيارة املقدر من أهل اخلبرة واعتبار احلكم حضوري ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/12/28 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33480821 :‬‬\n                         ‫َر ْق ُم الدعوى‪32590589 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34281929‬تاريخه‪1434/7/29 :‬هـ‬\n\n\n      ‫حــادث مــروري ‪ -‬تصــادم ســيارتني ‪ -‬مطالبــة بــأرش متلــف (ســيارة) ‪-‬‬\n      ‫تصحيــح الدعــوى علــى الكفيــل احلضــوري ‪ -‬االســتناد علــى قــرار أهــل‬\n      ‫اخلبــرة (تقديــر شــيخ املعــارض) ‪ -‬تضمــن الكفيــل احلضــوري لعجــزه‬\n      ‫عــن إحضــار مكفولــه ‪ -‬إلــزام املدعــى عليــه (الكفيــل) بــأرش تلــف‬\n                  ‫الســيارة املقــدر مــن أهــل اخلبــرة واعتبــار احلكــم حضوري ـ ًا ‪.‬‬\n\n\n\n      ‫‪ .1‬حديــث أبــي هريــرة يف قصــة اإلســرائيلي الــذي اســتلف مــن رجــل‬\n      ‫ألــف دينــار وقــال ائتنــي بشــهود قــال‪ :‬كفــى بــاهلل شــهيدا قــال‪ :‬فأتنــي‬\n      ‫بكفيــل قــال‪ :‬كفــى بــاهلل كفيــا وقــد ترجــم لــه البيهقــي ( بــاب يف‬\n      ‫الكفالــة بالبــدن) وبهــذا القــول قــال مالــك وأبــو حنيفــة وهــو املرجــح‬\n             ‫عنــد الشــافعية وحــكاه ابــن رشــد عــن جمهــور فقهــاء األمصــار‪.‬‬\n      ‫‪ .2‬قــول ابــن فرحــون يف تبصــرة احلــكام « فــرع ‪ :‬وكذلــك يرجــع إلــى‬\n      ‫أهــل املعرفــة مبســائل الضــرر ممــا يحدثــه اإلنســان علــى جــاره أو يف‬\n                                            ‫الطرقــات و أنــواع ذلــك « (‪.)85/2‬‬\n      ‫‪ .3‬الكفيــل يضمــن مــا علــى مكفولــه إن تعــذر عليــه إحضــاره علــى‬\n      ‫الصحيــح مــن املذهب‪(.‬انظــر السلســبيل يف معرفــة الدليــل للبليهــي‬\n                                                                             ‫‪)112/2‬‬\n\n\n\n‫‪25‬‬\n\f‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه صــدم ســيارته ويطلــب‬\n‫إلزامــه بدفــع أرش التلــف ‪ -‬ثــم قــام املدعــي بتصحيــح دعــواه ضــد‬\n‫كفيــل املدعــى عليــه احلضــوري لعجــزه عــن إحضــار مكفولــه ‪ -‬جــرى‬\n‫توجيــه تبليــغ للكفيــل باحلضــور فلــم يحضــر ‪ -‬جــرى ســؤال املدعــي‬\n‫البينــة فقــرر بــأن بينتــه األوراق املرفقــة باملعاملــة ‪ -‬جــرى االطــاع علــى‬\n‫تقريــر املــرور املشــار فيــه للحــادث وجــد أن نســبة اإلدانــة علــى املدعــى‬\n‫عليــه كاملــة ‪ - %100‬جــرى االطــاع علــى تقديــر أهــل اخلبــرة ألرش‬\n‫التلــف بتقديــر قيمتهــا قبــل وبعــد احلــادث ‪ -‬طلبــت الدائــرة مــن املدعــي‬\n‫ميــن االســتظهار علــى دعــواه فحلــف ‪ -‬عليــه ولتصحيــح املدعــي وكالــة‬\n‫دعــواه علــى الكفيــل ولتخلفــه مــع تبلغــه وألن تخلفــه يجعلــه يف حكــم‬\n‫النــاكل عــن اجلــواب وقرينــة علــى دعــوى املدعــي وبنــاء علــى مــا تضمنتــه‬\n‫أوراق املعاملــة مــن بينــات رصــدت يف ضبــط القضيــة وألن األصــل عــدم‬\n‫التســديد ولبــذل املدعــي اليمــن التــي تشــرع يف جانــب أقــوى املتداعيــن‬\n‫ولقــوة جانــب املدعــي يف هــذه الدعــوى وألن للقاضــي االســتعانة بقــول‬\n‫أهــل اخلبــرة وألن الكفيــل يضمــن مــا علــى مكفولــه إن تعــذر عليــه‬\n‫إحضــاره‪ ،‬وبنــاء علــى ذلــك فقــد حكمــت الدائــرة علــى املدعــى عليــه‬\n‫الكفيــل بــأن يدفــع للمدعــي أرش التلــف املســتحق املقــدر مــن أهــل‬\n‫اخلبــرة واعتبــرت احلكــم يف حقــه حضوريــا وقــررت بعــث صــورة مــن‬\n‫صــك احلكــم للمدعــى عليــه وإفهامــه بتعليمــات االعتــراض ‪ -‬صــدق‬\n                                            ‫احلكم من محكمة االستئناف‪.‬‬\n\n\n\n                                                                                     ‫‪26‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n     ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32590589‬وتاريــخ‬\n     ‫‪1432/12/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321593797‬وتاريــخ‬\n     ‫‪1432/12/19‬ه ـ املتعلقــة بدعــوى ‪ .....‬ضــد ‪ .....‬ففــي هــذا اليــوم‬\n     ‫الســبت املوافــق‪1433/02/27‬ه افتتحــت اجللســة الســاعة ‪09 : 15‬‬\n     ‫وفيهــا حضــر املدعــي ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه ويف يــوم األحــد املوافــق‬\n     ‫‪1433/04/25‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ‪.....‬‬\n     ‫ســجل مدنــي رقــم ‪ .....‬بوكالتــه عــن ‪ .....‬الصــادرة مــن كتابــة عــدل‬\n     ‫الثانيــة بغــرب مكــة برقــم ‪ 331230‬يف ‪1433/1/1‬ه ـ املخــول لــه فيهــا‬\n     ‫املرافعــة واملدافعــة واملطالبــة باحلقــوق والتعويضــات واســتالمها الــخ ولــم‬\n     ‫يحضــر املدعــى عليــه وال مــن ميثلــه ثــم ادعــى املدعــي وكالــة قائــا إنــه‬\n     ‫بتاريــخ ‪1432/12/4‬ه ـ ومبنطقــة الشــرائع وقــع حــادث مــروري عبــارة‬\n     ‫عــن تصــادم حيــث قــام املدعــى عليــه بصــدم ســيارة موكلــي مــن اجلهــة‬\n     ‫اليمنــى مــا أحلــق بهــا تلفيــات وأضــرار وقــد أديــن املدعــى عليــه بنســبة‬\n     ‫‪ % 100‬املســئولية الكاملــة عــن ذلــك احلــادث كمــا هــو موضــح مبحضــر‬\n     ‫النســبة املعتمــد مــن قبــل شــعبة احلــوادث بــإدارة مــرور العاصمــة املقدســة‬\n     ‫املرفــق باملعاملــة وقــد قــدرت مســتحقاتي املاليــة املترتبــة علــى املدعــى‬\n     ‫عليــه لقــاء ذلــك احلــادث الــذي تســبب فيــه مبلــغ قــدره واحــد وعشــرون‬\n     ‫ألــف ريــال لــذا فإنــي أطلــب احلكــم علــى املدعــى عليــه بدفع مســتحقاتي‬\n\n‫‪27‬‬\n\f‫املاليــة واملتمثلــة يف مبلــغ واحــد وعشــرين ألــف ريــال لقــاء احلــادث الــذي‬\n‫وصفــت وقائعــه يف دعــواي والــذي تســبب فيــه املدعــى عليــه هــذه دعــواي‬\n‫وأســأله اجلــواب احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق‬\n‫‪1433/09/12‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 00‬وفيهــا حضــر املدعي‬\n‫وكالــة ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وكانــت قــد وردتنــا‬\n‫أوراق التبليــغ برقــم ‪ 32/33/242818‬يف ‪1433/2/7‬ه ـ املتضمــن (لقــد‬\n‫ســلم التبليــغ لكفيلــه ‪...................‬وأفيــد أنــه لــدى املدعــى عليــه ســفر‬\n‫خــارج اململكــة يف تاريــخ اجللســة آمــل حتديــد موعــد جديد)‪.‬إ‪.‬هــ‪ .‬وتبليــغ‬\n‫رقــم ‪ 33/787443‬يف ‪1433/4/26‬ه ـ املتضمــن أنــه جــرى تســليم صــورة‬\n‫التبليــغ للمدعــو ‪ ................... /‬صفتــه موظــف باملؤسســة)‪.‬إ‪.‬هـ‪ .‬ثــم قــرر‬\n‫املدعــي وكالــة قائــا إنــي أطلــب تصحيــح دعــواي هــذه وتوجيههــا ضــد‬\n‫كفيــل املدعــى عليــه ‪ ...............‬حيــث كفلــه كفالــة حضوريــة هكــذا‬\n‫قــال ثــم جــرى تصفــح أوراق املعاملــة فوجــدت كفالــة حضوريــة علــى لفــة‬\n‫رقــم (‪ )3‬موافقــة ملــا عطــف عليهــا عليــه أمــرت بإعــادة إبــاغ املدعــو ‪/‬‬\n‫‪ ..............‬املذكــور للحضــور يف املوعــد احملــدد يف يــوم الثالثــاء املوافــق‬\n‫‪1433/11/23‬ه ـ الســاعة ‪ 10 : 30‬لإلجابــة عــن دعــوى املدعــي وكالــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪1433/9/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء ‪1433/11/23‬ه ـ‬\n‫أفتتحــت اجللســة متــام الســاعة ‪11 : 00‬وفيهــا حضــر املدعــي وكالــه‬\n‫وحضــر حلضــوره املدعــى ‪........................‬ســعودي اجلنســية بالســجل‬\n‫املدنــي رقــم‪ .......................‬ثــم قــرر األخيــر قائــا لقــد طلــب موكلــي‬\n‫تصحيــح دعــواي يف اجللســة املاضيــة علــى املدعــو‪ ......................‬حيــث‬\n\n\n                                                                                        ‫‪28‬‬\n\f     ‫أنــي أطلــب احلكــم عليــه بإلزامــه بدفــع املبلــغ املدعــى بــه وقــدره‬\n     ‫واحــد وعشــرون ألــف ريــال لقــاء كفالتــه املتســبب يف احلــادث املدعــو‬\n     ‫‪ .................. /‬كفالــه حضوريــه حيــث لــم يحضــر بذاتــه ولــم يحضــر‬\n     ‫مكفولــه هكــذا قــال وبتصفــح أوراق املعاملــة وجــدت ضمــن طياتهــا‬\n     ‫ورقــة تبليــغ برقــم ‪ 5/138/20‬املتضمنــة اســم املســتلم‪.......................‬‬\n     ‫صفتــه كفيــل املدعــى عليــه ووكيلــه وجدتهــا تضمنــت العبــارة التاليــة‬\n     ‫علم ـ ًا أن لــدي موعــد ســفر خــارج اململكــة يف تاريــخ اجللســة أ‪.‬ه ـ وقــد‬\n     ‫حــددت يف ورقــة التبليــغ جلســة يــوم الســبت ‪1433/2/27‬ه ـ ثــم ســألت‬\n     ‫املدعــي عــن بينتــه علــى دعــواه فأجــاب بقولــه إن بينتــي هــي مــا ورد‬\n     ‫يف أوراق املعاملــة وأطلــب الرجــوع إليهــا هكــذا قــال وبتصفــح أوراق‬\n     ‫املعاملــة وجــدت ضمــن طياتهــا محضــر نســبة إدانــة علــى اللفــة رقــم ‪16‬‬\n     ‫رقــم بــدون تاريــخ بــدون ويتضمــن بعــد االطــاع علــى األوراق اخلاصــة‬\n     ‫باحلــادث املــروري الــذي وقــع بتاريــخ ‪1432/12/4‬ه ـ اتضــح لنــا أنــه‬\n     ‫يــدان يف احلــادث املدعــو ‪ .................‬ســوداني اجلنســية باإلقامــة رقــم‬\n     ‫………………‪ .‬ســائق الســيارة مــن نــوع مرســيدس راس رقــم اللوحــة‬\n     ‫‪ .....................‬نســبة اإلدانة ‪ %100‬واملدعو ………………… ســعودي‬\n     ‫اجلنســية رقــم الهويــة ‪ ......................‬ســائق الســيارة مــن نــوع كامــري‬\n     ‫رقــم اللوحــة ‪ ...................‬وذلــك لألســباب اآلتيــة مباشــرة الطــرف األول‬\n     ‫للصــدم مبقدمــة ســيارته ودخولــه يف مســار الطريــق الثانــي وعــدم‬\n     ‫إعطــاء األفضليــة ملــن يســير يف مســاره الصحيــح وبعــض الطــرف الثانــي‬\n     ‫مــن النســبة كونــه يســير يف مســاره الصحيــح ولــم يرتكــب أي خطــأ‬\n     ‫أدى إلــي وقــوع احلــادث توقيــع ضابــط القضيــة ‪...............‬ضابــط محقــق‬\n     ‫‪ ..................‬رئيــس شــعبة احلــوادث املكلــف ‪ .............‬أ‪.‬ه ـ كمــا وجــدت‬\n\n\n‫‪29‬‬\n\f‫تقديــر ًا لشــيخ املعــارض وطائفــة داللــي حراجــات الســيارات العاصمــة‬\n‫املقدســة لفــة ‪12‬برقــم ‪ 5414‬وتاريــخ ‪1432/12/4‬ه ـ املتضمــن أن‬\n‫ســعر الســيارة الكامــري موديــل ‪ 2006‬ورقــم لوحتهــا‪ ............... ...‬قبــل‬\n‫احلــادث يقــدر مببلــغ تســعة وعشــرون ألــف ريــال تقريب ـ ًا وبعــد احلــادث‬\n‫يقــدر مببلــغ ثمانيــة آالف وخمســمائة ريــال تقريبـ ًا أ‪.‬ه ـ ثــم ســألت املدعي‬\n‫هــل لديــه مزيــد بينــة فأجــاب بالنفــي فطلبــت منــه اليمــن علــى صحــة‬\n‫ا واهلل العظيــم الــذي ال إلــه إال هــو عالــم الغيــب‬        ‫دعــواه فحلــف قائ ـ ً‬\n‫والشــهادة بأنــه بتاريــخ ‪1432/12/4‬ه ـ ومبنطقــة الشــرائع وقــع حــادث‬\n‫مــروري عبــارة عــن تصــادم حيــث قــام املدعــو ‪ .............................‬بصــدم‬\n‫ســيارتي مــن اجلهــة اليمنــى وأحلــق بهــا تلفيــات وأضــرار وقــد أديــن بنســبة‬\n‫‪ %100‬عــن ذلــك احلــادث وقــد قــدرت مســتحقاتي املاليــة املترتبــة عليــه‬\n‫لقــاء ذلــك احلــادث الــذي تســبب فيــه مبلــغ قــدره واحــد وعشــرون ألــف‬\n‫ريــال وقــد كفلــه املدعــو ‪ ................‬كفالــة حضوريــه و غرميــه وأنــه‬\n‫لــم يصلنــي شــيء مــن املبلــغ املدعــى بــه ولــم أبــرئ منــه واهلل العظيــم‬\n‫) فبنــاء علــى مــا تقــدم مــن الدعــوى ولتصحيــح املدعــي وكالــة دعــواه‬\n‫وطلــب املدعــي أمضــاء ذلــك وتوجيههــا علــى الكفيــل ولتخلفــه مــع تبلغــه‬\n‫وألن تخلفــه يجعلــه يف حكــم النــاكل عــن اجلــواب وقرينــة علــى دعــوى‬\n‫املدعــي وبنــاء علــى مــا تضمنتــه أوراق املعاملــة مــن بينــات رصــدت بعاليــه‬\n‫و ألن األصــل عــدم التســديد ولبــذل املدعــي اليمــن التــي تشــرع يف جانب‬\n‫أقــوى املتداعيــن ولقــوة جانــب املدعــي يف هــذه الدعــوي وألنــه قــد يحتاج‬\n‫محــل النــزاع املعــروض علــى احملكمــة الــى رأي أهــل اخلبــرة فللقاضــي‬\n‫االســتعانة بقولهــم ملــا لهــم مــن عالمــات حســية متكنهــم مــن املعرفــة ويف‬\n‫ذلــك يقــول ابــن فرحــون يف تبصــرة احلــكام ( فــرع ‪ :‬وكذلــك يرجــع‬\n\n\n                                                                                         ‫‪30‬‬\n\f     ‫الــى أهــل املعرفــة مبســائل الضــرر ممــا يحدثــة اإلنســان علــى جــاره أو يف‬\n     ‫الطرقــات و أنــواع ذلــك ) (‪ )85/2‬ولرضــى املدعى عليه نصار بالكفالة‬\n     ‫والتــي تظهــر يف كفالتــه للمتســبب ‪...................‬يحررهــا كمــا يف اللفــة‬\n     ‫الثالثــة مــن أوراق املعاملــة و ألن الكفالــة تصــح بــكل عــن مضمونــه‬\n     ‫وببــدن مــن عليــه ديــن و يف صحيــح البخــاري مــن حديــث أبــي هريــره‬\n     ‫يف قصــة اإلســرائيلي الــذي اســتلف مــن رجــل ألــف دينــار وقــال ائتنــي‬\n     ‫بشــهود قــال كفــى بــاهلل شــهيدا قــال فأتنــي بكفيــل قــال كفــى بــاهلل‬\n     ‫كفيــا وقــد ترجــم لــه البيهقــي ( بــاب يف الكفالــة بالبــدن) وبهــذا‬\n     ‫القــول قــال مالــك وأبــو حنيفــه وهــو املرجــح عنــد الشــافعية وحــكاه‬\n     ‫ابــن رشــد عــن جمهــور فقهــاء األمصــار وعلــى الصحيــح مــن املذهــب إن‬\n     ‫تعــذر علــى الكفيــل إحضــار املكفــول ضمــن مــا عليــه وهــو اختيــار‬\n     ‫الشــيخ أنظــر السلســبيل حاشــية علــى زاد املســتقنع ‪ .‬البليهــي ‪.112/2‬‬\n     ‫بنــاء علــى ذلــك فقــد حكمــت علــى املدعــى عليــه ‪............................‬‬\n     ‫بــأن يدفــع للمدعــي ‪ .........................‬املبلــغ املدعــى بــه و قــدره واحــد و‬\n     ‫عشــرون ألــف ريــال وبذلــك حكمــت واعتبرتــه حضوريــا يف حــق املدعــى‬\n     ‫عليــه وســوف يتــم إبالغــه بنســخه مــن احلكــم لتقــدمي مــا لديــه حيالــه‬\n     ‫مــن اعتــراض خــال ثالثــن يومــا مــن تاريــخ االســتالم فــأن لــم يفعــل‬\n     ‫خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب احلكــم القطعيــة‬\n     ‫وبــاهلل التوفيــق وصــل اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫حــرر يف ‪1433/11/23‬ه ـ احلمــد هلل وحــده وبعــد لــدي أنــا ‪...................‬‬\n     ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة القائــم بعمــل فضيلــة‬\n     ‫الشــيخ ‪ ...................‬خــال فتــرة إجازتــه حيــث عــادت أوراق املعاملــة مــن‬\n     ‫محكمــة االســتئناف باخلطــاب رقــم ‪ 321593797‬يف ‪1434/8/21‬ه ـ‬\n\n\n‫‪31‬‬\n\f‫رفقهــا الصــك الشــرعي رقــم ‪ 33480821‬يف ‪1433/12/28‬ه ـ مظهــر ًا‬\n‫عليــه بقــرار الدائــرة احلقوقيــة اخلامســة مبحكمــة االســتئناف رقــم‬\n‫‪ 34281929‬يف ‪1434/7/29‬ه ـ املتضمــن أنــه بدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــررت باألكثريــة املوافقــة علــى احلكم‬\n‫‪ .‬قاضــي اســتئناف ختــم وتوقيــع‪ ( ................... /‬لــي وجهــة نظــر ‪ /‬قاضي‬\n‫اســتئناف ختــم وتوقيــع ‪ / ................ /‬رئيــس اســتئناف ختــم وتوقيــع‬\n‫‪ ......................./‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1434/10/14‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n‫‪321593797‬وتاريــخ ‪1434/7/5‬ه املرفــق بهــا الصــك رقــم ‪33480821‬‬\n‫وتاريخ‪1433/12/28‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪..................../‬‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة املتضمــن دعــوى‪............/‬‬\n‫‪................‬ســعودي اجلنســية ضد ‪ ........................../‬ســوداني اجلنســية يف‬\n‫إتــاف ممتلــكات‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا باألكثريــة املوافقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪32‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":25,"source_page_end":32,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4f253507806c1bd9f26bae6b1e834aab2fe40d4cee0d3244960f81ba0382fe66","normalized_text_hash":"70804a09b3f995b3d6d0589c2fe0aac4f1c66e873f1920088d97c34043e5bc7e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p25-33480821"},{"id":"a23c165c-f1be-5498-beed-207798ca3ab0","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -مطالبة املؤجر بأرش التلف من املستأجر لتعديه بتسليم السيارة لغيره من غير إذن منها مخالف ا شرط العقد -دفع املدعى عليه بعدم التعدي وأن سبب احلادث خلل فني -احلكم بإلزام املدعى عليه بدفع االرش -رفع املعاملة حملكمة الاستئناف لتعذر تسليم احلكم للمدعى عليه.","document_number":"33415596","case_number":"33226640","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/19","year":"1434","subject":"حادث مروري -مطالبة املؤجر بأرش التلف من املستأجر لتعديه بتسليم السيارة لغيره من غير إذن منها مخالف ا شرط العقد -دفع املدعى عليه بعدم التعدي وأن سبب احلادث خلل فني -احلكم بإلزام املدعى عليه بدفع االرش -رفع املعاملة حملكمة الاستئناف لتعذر تسليم احلكم للمدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/9/19 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33415596 :‬‬\n                        ‫َر ْق ُم الدعوى‪33226640 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34204163‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬مطالبــة املؤجــر بــأرش التلــف مــن املســتأجر لتعديــه‬\n     ‫بتســليم الســيارة لغيــره مــن غيــر إذن منهــا مخالفـ ًا شــرط العقــد ‪ -‬دفــع‬\n     ‫املدعــى عليــه بعــدم التعــدي وأن ســبب احلــادث خلــل فنــي ‪ -‬احلكــم‬\n     ‫بإلــزام املدعــى عليــه بدفــع االرش ‪ -‬رفــع املعاملــة حملكمــة االســتئناف‬\n                                         ‫لتعــذر تســليم احلكــم للمدعــى عليــه‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله تعالى‪« :‬يا أيها اللذين آمنوا أوفوا بالعقود»‪.‬‬\n     ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم‪« :‬املســلمون علــى شــروطهم»رواه أبــو داود‬\n                           ‫وأحمــد والترمــذي وقــال هــذا حديــث حســن صحيح‪.‬‬\n     ‫‪ .3‬قــول ابــن رشــد ‪-‬رحمــه اهلل‪ -‬يف بدايــة املجتهــد ‪« : 231/2‬وال خــاف‬\n     ‫أنهــا ‪ -‬يعنــي الدابــة املســتأجرة ‪ -‬إذا تلفــت باملســافة املتعــداة أنــه ضامــن‬\n                                                                               ‫لها»أ‪.‬هـ‪.‬‬\n     ‫‪ .4‬وقــول ابــن قدامــة ‪-‬رحمــه اهلل‪ -‬يف املغنــي ‪ ... « : 79/5‬فأمــا إذا تلفــت‬\n     ‫حالــة تعــدٍ ولــم يكــن صاحبهــا مــع راكبهــا فــا خــاف يف ضمانهــا‬\n                                                                     ‫بكمــال القيمــة»‪.‬‬\n     ‫‪ .5‬الفقــرة (‪ )5/176‬مــن اللوائــح التنفيذيــة لنظــام املرافعــات الشــرعية‬\n     ‫ونصهــا «إذا تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى احملكــوم‬\n     ‫عليــه أو وكيلــه يرفــع احلكــم إلــى محكمــة التمييــز بــدون الئحــة‬\n                                                                          ‫اعتراضيــة»‪.‬‬\n‫‪33‬‬\n\f‫أقامــت شــركة دعــوى علــى املدعــى عليــه بأنــه اســتأجر منهــا ســيارة‬\n‫فــأذن البنــه بقيادتهــا فانقلــب بهــا وملــا تضمنــه أحــد بنــود العقــد مــن أن‬\n‫املســتأجر يضمــن كل مــا يلحــق الســيارة مــن تلــف إذا مكــن غيــره مــن‬\n‫قيادتهــا فهــي تطلــب إلــزام املدعــى عليــه بدفــع أرش التلــف وأجــرة نقــل‬\n‫الســيارة مــن موقــع احلــادث ‪ -‬أقــر املدعــى عليــه بالعقــد وأنــه مكــن ابنــه‬\n‫مــن قيــادة الســيارة ودفــع بــأن احلــادث كان خللــل فنــي يف الســيارة حيــث‬\n‫انفتــح عليــه واقــي احملــرك أثنــاء الســير بهــا فحجبــت عنــه الرؤيــة ممــا‬\n‫أدى النقالبــه بهــا ‪ -‬طعــن املدعــى عليــه أيضــا بتقديــر أهــل اخلبــرة بأنهــم‬\n‫لــم يشــاهدوا العــن املتلفــة ‪ -‬تخلــف املدعــى عليــه عــن احلضــور اجللســة‬\n‫بعــد تبلغــه لشــخصه ‪ -‬جــرى اطــاع الدائــرة علــى وثيقــة العقــد ومــا‬\n‫تضمنتــه مــن شــروط منهــا عــدم الســماح لغيــر املســتأجر بقيــادة الســيارة‬\n‫وعلــى تقديــر شــيخ املعــارض ورصــد مضمونهمــا بضبــط القضيــة ‪ -‬عليه‬\n‫وألن الشــركة املدعيــة اشــترطت علــى املدعــى عليــه أن يســتويف املنفعــة‬\n‫املؤجــرة بنفســه أو مبــن يفــوض تفويضـ ًا رســمي ًا مــن قبلهــم وألن األصــل‬\n‫يف الشــروط اجلــواز والصحــة ولقولــه تعالــى‪« :‬يــا أيهــا الذيــن آمنــوا أوفــوا‬\n‫بالعقــود» ولقولــه صلــى اهلل عليــه وســلم ‪ »:‬املســلمون علــى شــروطهم»‬\n‫رواه أبــو داود وأحمــد والترمــذي وقــال هــذا حديــث حســن صحيــح ‪-‬‬\n‫وألن املدعــى عليــه أقــر بعــدم تفويــض ابنــه تفويضـ ًا رســمي ًا وألن الضمان‬\n‫منــوط بالتعــدي‪ ،‬واملدعــى عليــه قــد خالــف الشــرط فتعتبــر يــده واحلالــة‬\n‫هــذه يدعاديــة قــال ابــن رشــد رحمــه اهلل يف بدايــة املجتهــد ‪« : 231/2‬وال‬\n‫خــاف أنهــا ‪-‬يعنــي الدابــة املســتأجرة ‪-‬إذا تلفــت باملســافة املتعــداة أنــه‬\n\n                                                                                       ‫‪34‬‬\n\f     ‫ضامــن لهــا» أ‪.‬ه ـ وقــال ابــن قدامة‪-‬رحمــه اهلل‪ -‬يف املغنــي ‪... « : 79/5‬‬\n     ‫فأمــا إذا تلفــت حالــة تعــدٍ ولــم يكــن صاحبهــا مــع راكبهــا فــا خــاف‬\n     ‫يف ضمانهــا بكمــال القيمــة» ‪ ،‬لــذا كلــه فقــد حكمــت الدائــرة علــى‬\n     ‫املدعــى عليــه بــأن يســلم الشــركة املدعيــة أرش تلــف الســيارة محــل‬\n     ‫الدعــوى مــع تكلفــة نقلهــا ‪ -‬اعتبــرت الدائــرة احلكــم حضوريــا وقــررت‬\n     ‫بعــث صــورة الصــك للمدعــى عليــه وإفهامــه بتعليمــات االعتــراض ‪-‬‬\n     ‫وردت اإلفــادة مــن محضــر اخلصــوم بالوصــول ملنــزل املدعــى عليــه عــدة‬\n     ‫مــرات يف أوقــات مختلفــة ولــم يعثــر عليــه وأفــاد أحــد املجاوريــن أنــه لــم‬\n     ‫يــره منــذ فتــرة طويلــة عليــه وبنــاء علــى الفقــرة (‪ )5/176‬مــن اللوائــح‬\n     ‫التنفيذيــة لنظــام املرافعــات الشــرعية ونصهــا» إذا تعــذر تســليم نســخة‬\n     ‫صــك احلكــم الغيابــي إلــى احملكــوم عليــه أو وكيلــه يرفــع احلكــم‬\n     ‫إلــى محكمــة التمييــز بــدون الئحــة اعتراضيــة» عليــه فقــد قــررت إحلــاق‬\n     ‫ذلــك بالصــك وســجله ورفعــه حملكمــة االســتئناف ‪ -‬صــدق احلكــم مــن‬\n                                                                  ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......................‬القاضــي يف احملكمــة‬\n     ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33226640‬وتاريــخ‬\n     ‫‪1433/03/30‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33604249‬وتاريــخ‬\n     ‫‪1433/03/30‬ه ـ حضــر ‪ .......................‬ســجل مدني رقــم ‪.....................‬‬\n     ‫بصفتــه وكيــا عــن ‪ ......................‬الوكيــل عــن ‪...........................‬‬\n     ‫مديــر الشــركة ‪ ...‬للبيــع بالتقســيط احملــدودة مبوجــب صــك الوكالــة‬\n\n‫‪35‬‬\n\f‫الصــادر مــن كتابــة العــدل الثانيــة بشــمال جــدة برقــم ‪ 99012‬يف‬\n‫‪ /12/2‬واملخولــة لــه إقامــة وســماع الدعــاوي واملدافعــة واملرافعــة وتقــدمي‬\n‫البينــات وطلــب اليمني‪....‬إلــخ كمــا حضــر املدعــى عليــه ‪.......................‬‬\n‫ا‬\n‫ســجل مدنــي رقــم ‪ ، ................‬وبســؤال املدعــي عــن دعــواه أجــاب قائـ ً‬\n‫‪ :‬إن املدعــى عليــه اســتأجر منــا ســيارة يف ‪1429/8/18‬ه ـ نــوع ‪ ...‬وارد‬\n‫‪ ...‬رقــم الهيــكل ‪ .............‬رقــم اللوحــة ‪..............‬اللــون ‪ ...‬مبوجــب العقــد‬\n‫رقــم ‪ ....‬ملــدة ثمانيــة وأربعــن شــهر ًا ميالديــا ً تبــدأ مــن ‪2008/9/1‬م حتــى‬\n‫‪2012/8/1‬م بأجــرة إجماليــة قدرهــا ســتة وثمانــون ألف ـ ًا وأربعمائــة‬\n‫ريــال دفــع منهــا عنــد العقــد ألــف ريــال واألجــرة الشــهرية قدرهــا ألــف‬\n‫وثمامنائــة ريــال كمــا أن للمدعــى عليــه حــق متلك الســيارة بعــد انتهاء مدة‬\n‫التأجيــر مبوجــب عقــد جديــد يكتــب يف حينــه وقــد وقــع حــادث أثنــاء‬\n‫مــدة التأجيــر بتاريــخ ‪1431/3/6‬ه ـ علــى طريــق الســيل باجتــاه الطائــف‬\n‫بقيــادة ابــن املدعــى عليــه ‪ ........‬وكان احلــادث مــن طــرف واحــد وذلــك‬\n‫بانقــاب الســيارة وتلفهــا بالكامــل وقــدرت مــن قبــل شــيخ املعــارض قبل‬\n‫احلــادث مببلــغ قــدره ثالثــة وأربعــون ألــف ريــال وبعــد احلــادث مببلــغ قــدره‬\n‫اثنــا عشــر ألــف ريــال أطلــب إلــزام املدعــى عليــه بتســليم موكلتــي أرش‬\n‫التلفيــات وقــدره واحــد وثالثــون ألــف ريــال باإلضافــة إلــى مائتــي ريــال‬\n‫فاتــورة نقــل الســيارة مــن الشــركة إلــى شــيخ املعــارض وذلــك أن املدعــى‬\n‫عليه ســلم ابنه الســيارة بغير تفويض رســمي من قبل موكلتي وذلك أن‬\n‫الفقــرة الثالثــة مــن البنــد اخلامــس للعقــد تنــص علــى أن (يتحمــل الطــرف‬\n‫الثانــي تكاليــف إصــاح الســيارة املؤجــرة وتكاليــف األضــرار التــي‬\n‫تلحــق بركابهــا ســواء أكانــت إصابــات أوديــات وجميــع التكاليــف‬\n‫املترتبــة للغيــر مبــا يف ذلــك الديــة واإلصابــات وذلــك يف حالــة مــا إذا وقــع‬\n\n\n                                                                                            ‫‪36‬‬\n\f     ‫احلــادث وكان ســائق الســيارة محــل العقــد غيــر مفــوض بصفــة رســمية‬\n     ‫مــن قبــل الطــرف األول بقيادتهــا ســواء أكان ذلــك بعلــم الطــرف الثانــي‬\n     ‫أم بــدون علمــه) إ‪.‬ه ـ واملدعــى عليــه لــم يفــوض ابنــه تفويضـ ًا رســمي ًا هــذه‬\n     ‫ا ‪ :‬مــا ذكــره‬    ‫دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫املدعــي مــن االســتئجار بالعقــد واملــدة واألقســاط املذكــورة و قيــادة‬\n     ‫ابنــي للســيارة بــدون تفويــض مــن الشــركة ووقــوع احلــادث باالنقــاب‬\n     ‫فصحيــح إال أن ســبب احلــادث خلــل فنــي وذلــك أن كبوت الســيارة انفتح‬\n     ‫أثنــاء القيــادة فحجــب الرؤيــة فوقــع االنقــاب كمــا أننــي غيــر موافــق‬\n     ‫علــى تقديــر شــيخ املعــارض وذلــك ألن شــيخ املعــارض لم يشــاهد الســيارة‬\n     ‫قبــل احلــادث وعليــه فــا أوافقهــم علــى طلبهــم ألنهــم ال يســتحقون شــيئ ًا‬\n     ‫هكــذا أجــاب‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة ولــم يحضــر‬\n     ‫املدعــى عليــه وقــد جــرى االطــاع علــى العقــد بــن الطرفــن املطبوع على‬\n     ‫أوراق الشــركة ‪ ...................‬برقــم ‪ ...‬وتاريــخ ‪1429/8/18‬ه ــواملتضمن‬\n     ‫تأجيــر الشــركة املدعيــة علــى املدعــى عليــه الســيارة محــل الدعــوى‬\n     ‫للمــدة واألجــرة املذكورتــن‪ ،‬كمــا جــرى االطــاع علــى الفقــرة الثالثــة‬\n     ‫مــن البنــد اخلامــس فوجدتهــا طبــق مــا ذكــره املدعــي‪ ،‬كمــا جــرى‬\n     ‫االطــاع علــى الفقــرة الثانيــة عشــرة مــن البنــد تاســع ًا ونصهــا (ال يعــد‬\n     ‫هــذا العقــد تفويض ـ ًا مــن الطــرف األول للطــرف الثانــي أو ألي شــخص‬\n     ‫آخــر بقيــادة الســيارة املؤجــرة ‪ ،‬مــا لــم يحمــل الطرف الثاني أو الشــخص‬\n     ‫اآلخــر املفــوض بالقيــادة رخصــة قيــادة ســارية املفعــول وتفويضـ ًا كتابيـ ًا‬\n     ‫ال عــن‬ ‫ســاري املفعــول مــن الطــرف األول بقيــادة الســيارة املؤجــرة مســتق ً‬\n     ‫هــذا العقــد ‪ ،‬موقع ـ ًا ومختوم ـ ًا مــن قبــل الطــرف األول) ‪ ،‬كمــا جــرى‬\n     ‫االطــاع علــى تقديــر شــيخ املعــارض برقــم ‪ 0782‬يف ‪1433/3/26‬ه ـ‬\n\n\n‫‪37‬‬\n\f‫للســيارة محــل الدعــوى واملتضمــن تقديرهــا قبــل احلــادث بثالثــة وأربعــن‬\n‫ألــف ريــال وبعــد احلــادث باثنــي عشــر ألــف ريــال‪ ،‬فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ومــا جــرى االطــاع عليــه مــن العقــد بــن الطرفــن‬\n‫وتقدير شــيخ املعارض ومبا أن الشــركة املدعية اشــترطت على املدعى‬\n‫عليــه أن يســتويف املنفعــة املؤجــرة بنفســه أو مبــن يفــوض تفويضـ ًا رســمي ًا‬\n‫مــن قبلهــم ومبــا أن األصــل يف الشــروط يف العقــود اجلــواز والصحــة لقوله‬\n‫تعالــى ‪( :‬يــا أيهــا اللذيــن آمنــوا أوفــوا بالعقــود ) ولقولــه صلــى اهلل عليــه‬\n‫وســلم ‪( :‬املســلمون علــى شــروطهم) رواه أبــو داود وأحمــد والترمــذي‬\n‫وقــال هــذا حديــث حســن صحيــح إ‪.‬ه ـ ‪،‬ومبــا أن املدعــى عليــه صــادق‬\n‫علــى دعــوى املدعــي يف عــدم تفويــض ابنــه تفويض ـ ًا رســمي ًا والضمــان‬\n‫منــوط بالتعــدي واملدعــى عليــه قــد خالــف مــا تشــارط عليــه الطرفــان‬\n‫فتعتبــر يــده واحلالــة هــذه يــد عاديــة قــال ابــن رشــد رحمــه اهلل يف بدايــة‬\n‫املجتهــد ‪ ( : 231/2‬وال خــاف أنهــا «يعنــي الدابــة املســتأجرة « إذا تلفــت‬\n‫باملســافة املتعــداة أنــه ضامــن لهــا ( إ‪.‬ه ـ وقــال ابــن قدامــه رحمــه اهلل يف‬\n‫املغنــي ‪ ... ( : 79/5‬فأمــا إذا تلفــت حالــة تعــدٍ ولــم يكــن صاحبهــا مــع‬\n‫راكبهــا فــا خــاف يف ضمانهــا بكمــال القيمــة) ‪ ،‬لــذا كلــه فقــد‬\n‫حكمــت علــى املدعــى عليــه بــأن يســلم الشــركة املدعيــة أرش تلفيــة‬\n‫الســيارة محــل الدعــوى مــع تكلفــة نقلهــا وقــدره واحــد وثالثــون ألف ـ ًا‬\n‫ومائتــا ريــال ويعتبــر هــذا احلكــم يف حــق املدعــى عليــه حضوريـ ًا وقــررت‬\n‫بعــث نســخة مــن صــك احلكــم للمدعــى عليــه لالعتــراض يف مــدة ال‬\n‫تتجــاوز ثالثــن يوم ـ ًا مــن تاريــخ اســتالمه للنســخة فــإذا انقضــت املــدة‬\n‫ولــم يقــدم اعتراضــه يســقط حقــه يف االعتــراض ويكتســب احلكــم‬\n‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                         ‫‪38‬‬\n\f                                            ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/9/3‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد بعــث نســخة صك احلكــم وردنا خطاب محضري‬\n     ‫اخلصــوم رقــم ‪ 33/2274915‬يف ‪1434/2/4‬ه ـ واملتضمــن تعــذر تســليم‬\n     ‫صــورة الصــك للمدعــى عليــه ‪ ....................‬وأنــه ( مت الوصــول ملنــزل‬\n     ‫املذكــور عــدة مــرات يف أوقــات مختلفــة ولــم جنــد املذكــور وأفــاد أحــد‬\n     ‫املجاوريــن أنــه لــم يــرى املذكــور منــذ فتــرة طويلــة) ‪ ،‬وبنــاء علــى املــادة‬\n     ‫‪ 5/176‬مــن اللوائــح التنفيذيــة لنظــام املرافعــات الشــرعية التــي تنــص‬\n     ‫علــى ( أنــه إذا تعــذر تســليم نســخة صــك احلكــم الغيابــي إلــى احملكــوم‬\n     ‫عليــه أو وكيلــه يرفــع احلكــم إلــى محكمــة التمييــز بــدون الئحــة‬\n     ‫اعتراضيــة )‪ ،‬عليــه فقــد قــررت إحلــاق ذلــك بالصــك وســجله ورفعــه‬\n     ‫حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                  ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/9‬ه‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪:‬‬\n     ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n     ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪33604249‬‬\n     ‫وتاريــخ ‪1434/4/16‬ه ـ املرفــق بهــا الصــك رقــم ‪ 33415596‬وتاريــخ‬\n     ‫‪1433/9/19‬ه ـ الصــادر مــن فضيلــة الشــيخ‪...................... /‬القاضــي‬\n     ‫باحملكمــة العامــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى ‪......................‬‬\n     ‫ضــد‪.................. /‬يف دعــوى حقوقيــة احملكــوم فيــه مبــا دون باطنــه‬\n     ‫بدراســة احلكــم وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم واهلل‬\n        ‫املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":33,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"368b07f62287efb06dcf68f5c9016831214191a6c80aa606585a09e51cbe19c8","normalized_text_hash":"818de9f2c817a8f16ce1558db4a63f1e722d103a1b8b42eb5121df77af09a0b4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p33-33415596"},{"id":"09bc636d-18e4-5cc6-b78d-6753a4dc562b","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -اصطدام سيارتني -سائق السيارة ليس مالكها - االختاف يف تقدير األرش -رفض الصلح أو التنازل عن أي مبلغ -األخذ يف الغرم باألقل -التزام مالك السيارة مبا ترتب على سائقها -االستناد إلى تقرير املرور وتقييم أهل اخلبرة يف تقدير","document_number":"33357527","case_number":"33143924","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف -جري تسليم املبلغ احملكوم به وبذلك انتهت القضية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/27","year":"1434","subject":"حادث مروري -اصطدام سيارتني -سائق السيارة ليس مالكها - االختاف يف تقدير األرش -رفض الصلح أو التنازل عن أي مبلغ -األخذ يف الغرم باألقل -التزام مالك السيارة مبا ترتب على سائقها -االستناد إلى تقرير املرور وتقييم أهل اخلبرة يف تقدير","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/27 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33357527 :‬‬\n                    ‫َر ْق ُم الدعوى‪33143924 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 3460445‬تاريخه‪1434/3/11 :‬هـ‬\n\n\n ‫حــادث مــروري ‪ -‬اصطــدام ســيارتني ‪ -‬ســائق الســيارة ليــس مالكهــا ‪-‬‬\n ‫االختــاف يف تقديــر األرش ‪ -‬رفــض الصلــح أو التنــازل عــن أي مبلــغ‬\n ‫‪ -‬األخــذ يف الغــرم باألقــل ‪ -‬التــزام مالــك الســيارة مبــا ترتــب علــى‬\n ‫ســائقها ‪ -‬االســتناد إلــى تقريــر املــرور وتقييــم أهــل اخلبــرة يف تقديــر‬\n                                                                         ‫املبلــغ ‪.‬‬\n\n\n\n ‫قــول الســيوطى رحمــه اهلل ‪( :‬ويؤخــذ يف الغــرم باألقــل ‪ ،‬ولــه مأخــذان‪:‬‬\n ‫أحدهمــا ‪ :‬وهــو األظهــر أن األقــل متيقــن والزائــد مشــكوك فيــه ‪.‬‬\n         ‫والثانــي ‪ :‬أن التــي شــهدت باألقــل رمبــا أطلعــت علــى عيــب )‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي علــى املدعــى عليــه بأنــه كان يســير بســيارته يف الطريــق‬\n ‫العــام وجــاء أخ املدعــى عليــه وصــدم بــه مــن اخللــف بســيارة عائــدة‬\n ‫ملكيتهــا للمدعــى عليــه ‪ -‬أديــن أخ املدعــى عليــه بنســبة اخلطــأ كاملــة‬\n ‫‪ -‬مت تقديــر تلفيــات ســيارة املدعــى بثــاث تقديــرات متفاوتــة ‪ -‬طلــب‬\n ‫املدعــي إلــزام املدعــى عليــه بدفــع التقديــر األوســط ‪ -‬أقــر املدعــى عليــه‬\n ‫مبــا جــاء يف الدعــوى وقــرر أنــه يقــوم مقــام أخيــه قائــد الســيارة املباشــرة‬\n ‫للحــادث ‪ -‬قــرر املدعــى عليــه أن التقديــرات الثــاث مبالــغ فيهــا ‪ -‬ملــا‬\n\n                                                                                         ‫‪40‬‬\n\f     ‫قــرره أهــل العلــم مــن أن املتيقــن هــو األقــل يف األروش صــدر احلكــم‬\n     ‫بإلــزام املدعــى عليــه بدفــع أرش تلفيــات ســيارة املدعــى وفــق التقديــر‬\n     ‫األقــل ‪ -‬لــم يقتنــع املدعــى عليــه باحلكــم ‪ -‬صــدق احلكــم مــن محكمــة‬\n     ‫االســتئناف ‪ -‬جــري تســليم املبلــغ احملكــوم بــه وبذلــك انتهــت القضيــة ‪.‬‬\n\n\n\n\n     ‫ـدي‬\n       ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬فلـ َّ‬\n     ‫ـاء علــى املعاملــة الــواردة‬\n                                ‫أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n     ‫إلينــا مــن شــعبة مــرور محافظــة االحســاء بالرقــم ‪2827‬واملقيــدة بهــذه‬\n     ‫احملكمــة برقــم ‪33378975‬وتاريــخ ‪1433/02/27‬ه ـ واحملالــة لنــا مــن‬\n     ‫فضيلــة رئيــس احملكمــة برقم‪33143924‬وتاريخ‪1433/02/27‬ه ـ‬\n     ‫فتحــت اجللســة األولــى يف يــوم الثالثــاء ‪1433/06/24‬ه ـ الســاعة الثامنة‬\n     ‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)...‬‬\n     ‫وا َّدعــى علــى احلاضــر معــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫ا يف دعــواه ‪ :‬إننــي كنـ ُـت أســير بســيارتي بالقــرب مــن‬      ‫رقــم ‪ ...‬قائ ـ ً‬\n     ‫دوار ‪ ...‬وجــاء أخ املدعــى عليــه ‪ ...‬واصطــدم بــي مــن اخللــف بســيارة‬\n     ‫أخيــه ممــا أدى إلــى حصــول تلفيــات بســيارتي قــدرت ثــاث تقديــرات‬\n     ‫األول قبــل احلــادث بتســعة وعشــرين ألــف ريــال وبعــد احلــادث بســتة‬\n     ‫وعشــرين ألــف ريــال والفــارق ثالثــة آالف ريــال والتقديــر الثانــي قبــل‬\n     ‫احلــادث بثمانيــة وعشــرين ألــف ريــال وبعــد احلــادث بأربعــة وعشــرين ألــف‬\n     ‫ريــال والفــارق أربعــة آالف ريــال والتقديــر الثالــث قبــل احلــادث بخمســة‬\n     ‫وثالثــن ألــف ريــال وبعــده بواحــدٍ وثالثــن ألــف ريــال والفــارق ثالثــة‬\n     ‫آالف وخمســمائة ريــال وقــد أديــن الســائق بنســبة مائــة باملائــة أطلــب‬\n\n‫‪41‬‬\n\f‫احلكــم علــى املدعــى عليــه بدفــع أرش قيمــة ســيارتي وقــدره ثالثــة آالف‬\n‫وخمســمائة ريــال إضافــة إلــى تســعني ريــا ًال أجــرة تســعير الــورش الثــاث‬\n‫لســيارتي هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعــي أجــاب‬\n‫ا ‪ :‬مــا ذكــره املدعــي يف دعــواه مــن احلــادث ووقوعــه ونســبة اإلدانــة‬       ‫قائـ ً‬\n‫والتســعيرات وأجــرة الــورش الثــاث كل ذلــك صحيــح لكـ َّـن القائــد‬\n‫ـتعد بدفــع املبلــغ الــذي يحكــم بــه‬\n                                      ‫هــو أخــي ‪ ...‬وأنــا أقــوم مقامــه ومسـ ٌ‬\n‫والســيارة ســيارتي لكـ َّـن التســعيرات مبال ـ ٌغ فيهــا وأطلــب مــن املدعــي‬\n‫تخفيــض هــذا املبلــغ هكــذا أجــاب وبعــرض إجابــة املدعــى عليــه علــى‬\n‫ـتعد بالتنــازل عــن أي مبلــغ وال‬‫ا ‪ :‬إننــي لسـ ُـت مسـ ٌ‬     ‫املدعــي أجــاب قائ ـ ً‬\n‫ـاء علــى مــا تقــدم مــن‬\n                         ‫أريــد الصلــح مــع املدعــى عليــه هكــذا قــرر فبنـ ً‬\n‫أن املدعــى عليــه أقـ َّـر بدعــوى املدعــي وصــادق‬    ‫الدعــوى واإلجابــة ومبــا َّ‬\n‫علــى صحــة وقــوع احلــادث ونســبة إدانــة أخيــه والتزامــه بــأي مبلــغ يلــزم‬\n‫بــه واســتناد ًا إلــى تقريــر املــرور بإدانــة أخــي املدعــى عليــه بنســبة مائــة‬\n‫ـاء علــى قــرار أهــل اخلبــرة بتقييــم ســيارة املدعــي قبــل احلــادث‬ ‫باملائــة وبنـ ً‬\n‫أن املتيقــن هــو األقــل مــن األروش الثالثــة‬\n                                              ‫وبعــده وملــا قــرره أهــل العلــم مــن َّ‬\n‫قــال الســيوطي رحمــه اهلل‪( :‬ويؤخــذ يف الغــرم باألقــل ‪ ،‬ولــه مأخــذان‬\n‫‪ :‬أحدهمــا ‪ -‬وهــو األظهــر ‪ -‬أن األقــل متيقــن ‪ ،‬والزائــد مشــكوك‬\n‫فيــه ‪ ،‬فــا يلــزم بالشــك ‪ .‬والثانــي ‪ -‬أن التــي شــهدت باألقــل ‪ ،‬رمبــا‬\n‫اطلعــت علــى عيــب) لــذا فقــد ألزمــت املدعــى عليــه بدفــع مبلــغ وقــدره‬\n‫ـررت عــدم اســتحقاق املدعــي ملــا‬‫ثالثــة آالف وتســعون ريــا ًال للمدعــي وقـ ُ‬\n‫زاد عــن هــذا املبلــغ وبــه حكمـ ُـت وبعــرض احلكــم علــى الطرفــن قــررا‬\n‫عــدم قناعتهمــا باحلكــم وطلبــا متكينهمــا مــن تقــدمي الئحــة اعتراضيــة‬\n‫مت تســليمهما حــا ًال نســخة مــن احلكــم‬      ‫عليــه فأجيبــا إلــى طلبهمــا و َّ‬\n\n\n                                                                                            ‫‪42‬‬\n\f     ‫ـداء مــن هــذا اليــوم وإذا‬\n                               ‫ـأن مــدة االعتــراض ثالثــون يوم ـ ًا ابتـ ً‬‫وأفهمــا بـ َّ‬\n     ‫ـإن حقهمــا يف االســتئناف‬    ‫لــم يقدمــا اعتراضهمــا خــال هــذه املــدة فـ َّ‬\n     ‫يســقط ويكتســب القطعيــة فأبديــا فهمهمــا لذلــك وأقفلــت اجللســة‬\n     ‫الســاعة العاشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه أجمعــن ُحـ ِـر َر يف ‪1433/07/27‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n     ‫يــوم الثالثــاء ‪1433/08/06‬ه ـ فتحــت اجللســة الثالثــة الســاعة الواحــدة‬\n     ‫ـاء علــى الالئحــة املقدمــة مــن ‪ ...‬وقــد قيــدت‬‫وخمســة وأربعــن دقيقــة وبنـ ً‬\n     ‫هــذه الالئحــة باحملكمــة برقم ‪ 33/1454431‬بتاريــخ ‪1433/08/03‬هـ‬\n     ‫واملكونــة مــن صفحــه واحــده وقــد جــرى االطــاع علــى الالئحــة ولــم‬\n     ‫أجــد فيهــا مــا يوجــب الرجــوع عمــا حكمــت بــه وأمــرت برفــع كامــل‬\n     ‫أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وأقفلــت اجللســة‬\n     ‫الســاعة الثانيــة وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪1433/08/06‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي باحملكمــة اجلزئيــة‬\n     ‫باألحســاء ففــي هــذا اليــوم االحــد ‪1434/06/04‬ه ـ فتحــت اجللســة‬\n     ‫الســاعة الثانيــة عشــر والربــع وقــد عــادت إلينــا املعاملــة مــن مديــر‬\n     ‫شــعبة تنفيــذ األحــكام برقــم ‪ 9060‬تاريــخ ‪1434/05/27‬ه ـ واملقيــدة‬\n     ‫باحملكمــة برقــم ‪ 33373975‬واملرفــق بهــا الشــيك رقــم ‪034553‬‬\n     ‫وتاريــخ ‪1434/05/25‬ه ـ املســحوب علــى البنــك ‪ ...‬مببلــغ (‪ 3090‬ريــال)‬\n     ‫وحضــر لــدي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)...‬‬\n     ‫وجــرى تســليمه الشــيك املذكــور أعــاه وعليــه جــرى التوقيــع وأمــرت‬\n     ‫بالتهميــش علــى صكــه مبــا طــرأ عليــه وأقفلــت اجللســة الســاعة الثانيــة‬\n\n\n‫‪43‬‬\n\f‫عشــر والنصــف وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                ‫حــرر يف ‪1434/06/04‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى‬\n‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n‫واملقيــدة لدينــا برقــم ‪34/181824‬‬\n                                 ‫ّ‬     ‫‪ 34/23347‬وتاريــخ ‪1434/1/18‬ه ـ‬\n‫وتاريــخ ‪1434/1/20‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ‪ ... /‬املسـ ّـجل برقــم ‪ ...‬وتاريــخ ‪1433/7/27‬ه ـ اخلــاص‬\n‫بدعــوى‪ ... /‬ضــد‪ ... /‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحتــن االعتراضيتــن وأوراق املعاملــة قررنــا املصادقة على احلكم‬\n‫بعــد اإلجــراء األخيــر ‪ ،‬ولبيانــه جــرى حتريــره يف ‪1434/3/11‬هـ ‪ ،‬واهلل‬\n                                                              ‫ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                  ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":40,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa1d6eec07d080659ef2fcd9395886273a47b63a137203eb96ee4a2a63ebd093","normalized_text_hash":"104b1c845a5be31507c29390768c2ac58659b6568d309b7f519c7c4a5e3f586d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p40-33357527"},{"id":"c8e8346c-ba5a-5f7e-bca5-a04eb8131b7e","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -صدم سيارة من اخللف -مطالبة املدعي بدفع أرش إصابته وإصابة زوجته وتلفيات سيارته -إثبات نسبة اإلدانة مبوجب تقرير املرور -دفع مالك السيارة بعدم قيادته لها وقت احلادث -الدفع بسرقة السيارة املباشرة للحادث -وقوع احلادث قبل إباغ صاحب السيارة عن سرقتها -األصل أن العن اململوكة بيد مالكها -إدانة املدعى عليه بكامل اخلطأ ودفع مقابل ما حلق بالسيارة من نقص وأرش إصابة املدعي وزوجته .","document_number":"33366840","case_number":"33159100","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/4","year":"1434","subject":"حادث مروري -صدم سيارة من اخللف -مطالبة املدعي بدفع أرش إصابته وإصابة زوجته وتلفيات سيارته -إثبات نسبة اإلدانة مبوجب تقرير املرور -دفع مالك السيارة بعدم قيادته لها وقت احلادث -الدفع بسرقة السيارة املباشرة للحادث -وقوع احلادث قبل إباغ صاحب السيارة عن سرقتها -األصل أن العن اململوكة بيد مالكها -إدانة املدعى عليه بكامل اخلطأ ودفع مقابل ما حلق بالسيارة من نقص وأرش إصابة املدعي وزوجته .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/8/4 :‬هـ‬\n                     ‫ُ‬                 ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33366840 :‬‬\n                        ‫َر ْق ُم الدعوى‪33159100 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 33366840‬تاريخه‪1433/8/4 :‬هـ‬\n\n\n     ‫حــادث مــروري ‪ -‬صــدم ســيارة مــن اخللــف ‪ -‬مطالبــة املدعــي بدفــع‬\n     ‫أرش إصابتــه وإصابــة زوجتــه وتلفيــات ســيارته ‪ -‬إثبــات نســبة اإلدانــة‬\n     ‫مبوجــب تقريــر املــرور ‪ -‬دفــع مالــك الســيارة بعــدم قيادتــه لهــا وقــت‬\n     ‫احلــادث ‪ -‬الدفــع بســرقة الســيارة املباشــرة للحــادث ‪ -‬وقــوع احلــادث‬\n     ‫قبــل إبــاغ صاحــب الســيارة عــن ســرقتها ‪ -‬األصــل أن العــن اململوكــة‬\n     ‫بيــد مالكهــا ‪ -‬إدانــة املدعــى عليــه بكامــل اخلطــأ ودفــع مقابــل مــا حلــق‬\n                          ‫بالســيارة مــن نقــص وأرش إصابــة املدعــي وزوجتــه ‪.‬‬\n\n\n\n\n                                   ‫قاعدة‪ :‬األصل أن العني اململوكة بيد مالكها ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي أصالــة عــن نفســه وبوكالتــه عــن زوجتــه علــى املدعــى‬\n     ‫عليــه بــأن ســيارته تعرضــت للصــدم مــن اخللــف مــن قبــل ســيارة ملكيتهــا‬\n     ‫عائــدة للمدعــى عليــه ‪ -‬انقلبــت ســيارة املدعــي وتعــرض هــو وزوجتــه‬\n     ‫إلصابــات كمــا تعرضــت ســيارته لبعــض التلفيــات ‪ -‬لــم يتمكــن‬\n     ‫املدعــي مــن معرفــة الســائق لهروبــه والنقــاب ســيارة املدعــي ألن الصدم‬\n     ‫كان مــن اخللــف ‪ -‬صــدر تقريــر املــرور بإدانــة املدعــى عليــه بنســبة‬\n     ‫اخلطــأ ‪ - %100‬طلــب املدعــي إلــزام املدعــى عليــه بدفــع أرش إصابتــه‬\n\n‫‪45‬‬\n\f‫وإصابــة زوجتــه وكذلــك أرش تلفيــات ســيارته ‪ -‬أقــر املدعــى عليــه بــأن‬\n‫الســيارة املباشــرة للحــادث ملكيتهــا لــه ‪ -‬دفــع املدعــى عليــه بأنــه لــم‬\n‫يكــن يقــود الســيارة حيــث أن الســيارة قــد ســرقت منــه وقــام بتقــدمي‬\n‫بــاغ بالســرقة ‪ -‬جــرى رجــوع القاضــي إلــى تقريــر املــرور ‪ -‬كمــا جــرى‬\n‫الرجــوع إلــى تقديــر أرش إصابــة املدعــى وزوجتــه وأرش تلفيــات الســيارة‬\n‫‪ -‬حيــث إن احلــادث وقــع بتاريــخ ‪1433/1/13‬ه ـ الســاعة ‪ 12:30‬ظهــر ًا‬\n‫واملدعــى عليــه بلــغ عــن ســرقة ســيارته بنفــس التاريــخ وفــى متــام الســاعة‬\n‫الواحــدة والربــع ظهــر ًا حســب إفــادة املــرور ‪ -‬وحيــث أن األصــل يف‬\n‫العــن اململوكــة بقاؤهــا بيــد مالكهــا لــذا صــدر احلكــم بإدانــة املدعــى‬\n‫عليــه بنســبة اخلطــأ كاملــة حســب تقريــر املــرور واحلكــم عليــه بدفــع‬\n‫أرش إصابــة املدعــي وزوجتــه وكذلــك أرش تلفيــات ســيارته املذكــور‬\n‫قيمــة ذلــك يف منطــوق احلكــم ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‬\n‫‪ -‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف مبالحظــات أهمهــا‬\n‫رفــع البصمــات مــن الســيارة املتســببة يف احلــادث العائــدة للمدعــى عليــه‬\n‫للتأكــد مــن قائدهــا وقــت وقــوع احلــادث ‪ -‬أجــاب فضيلتــه بفــوات محلــه‬\n‫ألن رفــع البصمــات ال بــد أن يكــون خــال املــدة العلميــة وهــى ثمــان‬\n             ‫وأربعــون ســاعة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة بالرياض‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض برقــم ‪ 33159100‬وتاريــخ ‪31433/5‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 33393586‬وتاريــخ ‪1433/2/29‬ه ـ ففــي يــوم الســبت املوافــق‬\n\n                                                                                     ‫‪46‬‬\n\f     ‫‪1433/3/26‬ه ـ افتتحــت اجللســة وحضــر فهيــا ‪ ...‬ســعودي اجلنســية‬\n     ‫مبوجــب ســجل مدنــي رقــم ‪ ...‬وحضــر حلضــوره ‪ ...‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬األول قائــا إنــه بتاريــخ ‪1433/1/13‬ه ـ‬\n     ‫تعرضــت حلــادث تصــادم مــن قبــل ســيارة ميلكهــا املدعــى عليــه مــن نــوع‬\n     ‫كامــري وقــد جنــم عــن هــذا احلــادث إصابتــي وزوجتــي بعــدة كســور‬\n     ‫وتلفيــات بســيارتي قــدرت بأربعــن ألــف ريــال وحيــث إن نســبة اخلطــأ‬\n     ‫يف هــذا احلــادث هــي مائــة باملائــة علــى ســائق الســيارة لــذا اطلــب تقديــر‬\n     ‫أرش إصابتــي وقيمــة الســيارة واحلكــم علــى املدعــى عليــه بتســليمها‬\n     ‫لــي وأنــا لــم أمتكــن مــن معرفــة الســائق ألنــه اصطــدم بــي مــن اخللــف‬\n     ‫وانقلبــت ســيارتي فهــرب بعدهــا فلــم أمتكــن مــن معرفتــه هــذه دعــواي‬\n     ‫وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره املدعــي يف دعــواه ال‬\n     ‫أدري عنــه وال شــان لــي بــه فســيارتي مســروقة وقــد بلغــت عــن ســرقتها‬\n     ‫والبــاغ مرفــق باملعاملــة كمــا أننــي عســكري ومرابــط يف العمــل‬\n     ‫حتــى الســاعة الواحــدة ظهــرا مــن نفــس اليــوم الــذي وقــع فيــه احلــادث‬\n     ‫هكــذا أجــاب وبالرجــوع ألوراق املعاملــة عثــر مــن بينهــا علــى تقريــر‬\n     ‫حــادث املــرور لفــة رقــم ( ) وباالطــاع عليــه وجدتــه يتضمــن أن نســبة‬\n     ‫اخلطــأ يف هــذا احلــادث ترتبــت علــى قائــد الســيارة كاملــة بنســبة ‪%100‬‬\n     ‫كمــا جــرى االطــاع علــي تقديــر قيمــة النقــص الــذي حلــق بســيارة‬\n     ‫املدعــى فتبــن انــه أربعــون ألــف ريــال حــرر يف ‪1433/3/26‬ه ـ ويف‬\n     ‫جلســة أخــرى يــوم األربعــاء املوافــق ‪1433/5/12‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة الثامنــة والنصــف وحضــر فيهــا املدعــي واملدعــى عليــه وابــرز‬\n     ‫لنــا املدعــي التقريريــن الصادريــن مــن مدينــة امللــك عبــد العزيــز الطبيــة‬\n     ‫و مستشــفى امللــك فهــد برقــم ‪ ...‬وتاريــخ ‪1433/4/4‬ه ـ والثانــي برقــم ‪....‬‬\n\n\n‫‪47‬‬\n\f‫وتاريــخ ‪1433/4/5‬ه ـ حــرر يف ‪1433/5/12‬ه ـ ويف جلســة أخــرى يــوم‬\n‫الســبت املوافــق ‪1433/8/3‬ه ـ افتتحــت اجللســة الســاعة الواحــدة ظهــر ًا‬\n‫وحضــر فيهــا طــريف الدعــوى كمــا أحضــر املدعــي وكالــة عــن زوجتــه‬\n‫املصابــة معــه يف نفــس احلــادث مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 3399368‬وتاريــخ ‪1433/6/3‬ه ـ‬\n‫واملتضمنــة املطالبــة وإقامــة الدعــوى واإلقــرار واإلنــكار والتنــازل‬\n‫ا لقــد حصــل احلــادث لــي ولزوجتــي وقــد حلــق بهــا‬ ‫والصلــح وأضــاف قائـ ً‬\n‫إصابــات كثيــرة وهــي تطالــب تســليمها أرش إصاباتهــا وبعرضــه علــى‬\n‫املدعــى عليــه قــال ليــس لــدي ســوى مــا أجبــت بــه ســابق ًا هــذا وقــد وردني‬\n‫خطــاب مــن جلنــة تقديــر الشــجاج باحملكمــة رقــم ‪ 33393586‬وتاريــخ‬\n‫ا فقــد اجتمعــت جلنــة مقــدري الشــجاج‬      ‫‪1433/6/23‬ه ـ ونصــه كام ـ ً‬\n‫باحملكمــة العامــة بالريــاض وأطلعــت علــى املعاملــة رقــم ‪33393586‬‬\n‫وتاريــخ ‪1433/5/15‬ه ـ الــواردة مــن فضيلتكــم واملتضمنــة طلــب‬\n‫تقديــر إصابــة‪ .../‬وبعــد االطــاع علــى املعاملــة ومراجعــة التقريــر الطبــي‬\n‫ومبشــاهدة املصــاب ‪ ...‬تبــن أنــه أصيــب بحــرق احتكاكــي بالطــرف‬\n‫الســفلي األيســر قدرنــاه باثنــي عشــر ألــف ريــال (‪)12000‬حكومــة‪،‬‬\n‫وخــدوش باليــد اليســرى قدرنــا كل خــدش بألــف وخمســمائة ريــال‬\n‫(‪ )1500‬حكومــة‪ ،‬وال نعلــم عددهــا ‪ ،‬وجــرح قطعــي بالكــوع األيســر‬\n‫قدرناه بســتة آالف ريال (‪ )6000‬حكومة‪ ،‬وســحبات بالســاق اليســرى‬\n‫مــع فقــدان للجلــد قدرنــا كل ســحبة بألــف وخمســمائة ريــال (‪)1500‬‬\n‫حكومــة وال نعلــم عددهــا وقدرنــا فقــدان اجللــد بتســعة آالف ريــال‬\n‫(‪ )9000‬حكومــة‪ ،‬أمــا املصابــة ‪ ...‬وبــدون مشــاهدتها فقــد تبــن وجــود‬\n‫آالم بالضلــوع علــى اجلهــة اليســرى األماميــة أســفل الثــدي ناجتــة عــن‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫رضــه قدرناهــا بســتة آالف ريــال (‪ )6000‬حكومــة وآالم أســفل الظهــر‬\n     ‫نتيجــة رضــه قدرناهــا بأربعــة أالف وخمســمائة ريــال (‪ )4500‬حكومــة‬\n     ‫‪ ،‬وكدمــات بالظهــر والكتــف األيســر والفخــذ األيســر والســاق‬\n     ‫قدرنــا كل كدمــة بألــف وخمســمائة ريــال (‪ )1500‬حكومــة واجلميــع‬\n     ‫بأربعــة آالف وخمســمائة ريــال (‪ )4500‬حكومــة ورض علــى الصــدر‬\n     ‫والبطــن قدرنــاه بثالثــة آالف ريــال (‪ )3000‬حكومــة واهلل املوفــق أ‪.‬ه ـ‬\n     ‫وبعرضــه علــى املدعــي أصالــة ووكالــة قــال وموكلتــي نكتفــي مبــا‬\n     ‫ورد يف التقريــر وال نرغــب يف الكتابــة لبيــان عــدد الســحبات واخلــدوش‬\n     ‫هكــذا أقــر وباالطــاع علــى خطــاب مديــر إدارة املــرور بالريــاض رقــم‬\n                                           ‫‪ 925/31/2/7‬وتاريــخ ‪1433/2/24‬ه ـ‬\n     ‫املتضمــن أن تاريــخ بــاغ الهــروب يف يــوم ‪1433/1/13‬ه ـ الســاعة‬\n     ‫الواحــدة والربــع ظهــر ًا ومبطابقتــه مــع تقريــر املــرور املرفــق لفــة ‪ 1‬تبــن‬\n     ‫أن احلــادث وقــع يف يــوم ‪1433/1/13‬ه ـ الســاعة ‪12:30‬الثانيــة عشــر‬\n     ‫والنصــف ظهــر ًا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n     ‫احلــادث وقــع قبــل بــاغ املدعــى عليــه بالســرقة وألن األصــل أن أمــاك‬\n     ‫النــاس تكــون حتــت أيديهــم ومبــا أن الشــرطة واملــرور لــم يثبتــوا أن‬\n     ‫الســيارة كانــت بيــد أخــرى مــن خــال وســائل اإلثبــات كالبصمــات‬\n     ‫لــذا فقــد حكمــت علــى املدعــى عليــه بتســليم املدعــي ســبعون ألــف‬\n     ‫ريــال ‪ ،‬أربعــون ألــف ريــال منهــا لقــاء مــا حلــق بســيارته مــن نقــص وثالثــون‬\n     ‫ألــف ريــال مقابــل أروش اإلصابــات التــي حلقــت بــه كمــا حكمــت علــى‬\n     ‫املدعــى عليــه بتســليم املدعيــة ‪ ...‬ثمانيــة عشــر ألــف ريــال لقــاء مــا حلــق‬\n     ‫بهــا مــن إصابــات وبعرضــه علــى اجلميــع قــرر املدعــي أصالــة ووكالــة‬\n     ‫القناعــة كمــا قــرر املدعــى عليــه عدمهــا وطلــب االســتئناف بالئحــة‬\n\n\n‫‪49‬‬\n\f‫فأجبتــه لطلبــة وجــرى تزويــده بصــورة مــن صــك احلكــم وجــرى إفهامــه‬\n‫بــأن إذا لــم يقــدم الئحتــه خــال ثالثــن يومـ ًا مــن تاريــخ اليــوم فــإن حقــه‬\n‫يف االســتئناف ســاقط واحلكــم نافــذ ففهــم ذلــك‪ .‬وبــاهلل التوفيــق حــرر‬\n                                                                  ‫يف ‪1433/8/3‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/03/18‬ه ـ‬\n‫ويف متــام الســاعة الواحــدة افتتحــت اجللســة وقــد وردنــي قــرار محكمــة‬\n‫االســتئناف رقــم ‪ 3436090‬وتاريــخ ‪1434/02/12‬ه ـ ونصــه وبدراســة‬\n‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ‬\n‫مايلــي ‪ -1‬إجابــة املدعــى عليــه مشــمولة بأنــه كان مرابط ـ ًا يف عملــه‬\n‫حتــى الواحــدة ظهــر ًا مــن ذلــك اليــوم الــذي وقــع احلــادث ثــم علــم بســرقة‬\n‫ســيارته وبحــث عنهــا ثــم تقــدم ببــاغ ســرقة واملتعــن علــى فضيلتــه‬\n‫التأكــد مــن صحــة ذلــك عــن طريــق الكتابــة إلــى عمــل املدعــى عليــه‬\n‫لتحديــد عملــه وخروجــه يــوم احلــادث محــل الدعــوى وتقريــر مــا يظهــر لــه‬\n‫‪ -2‬لــم يصــرح فضيلتــه مبوجــب إدانــة قائــد الســيارة األخــرى بواقــع مائــة‬\n‫باملائــة كمــا لــم يصــرح مبوجــب نقــص قيمــة ســيارة املدعــي ومصــدره‬\n‫والبــد مــن ذلــك ‪ -3‬لــم يطلــع فضيلتــه علــى اســتمارة ملكيــة ســيارة‬\n‫املدعــي واملدعــى عليــه وتدويــن مضمونهــا ‪ -4‬يتوجــه مناقشــة املدعــى‬\n‫عليــه عــن مضمــون تقريــر املــرور ونســبة اإلدانــة وتدويــن القناعــة مــن‬\n‫عدمهــا ‪ -5‬تضمــن خطــاب ســعادة مديــر مــرور الريــاض املرفــق باملعاملــة‬\n‫وطلبــه مــن ســعادة مديــر شــرطة املعــذر تكليــف فنــي لديهــم باالنتقــال‬\n‫إلــى الســيارة باحلجــز وتصويرهــا ورفــع مــا عليهــا مــن اثــر يفيد الكشــف‬\n‫عــن هويــة الســائق واملتوجــه اطــاع فضيلتــه علــى هــذا اخلطــاب والرفــع‬\n‫إلــى اجلهــة املختصــة ملطابقــة بصمــة املدعــى عليــه علــى ذلــك األثــر أن‬\n\n\n                                                                                        ‫‪50‬‬\n\f     ‫وجــد ‪ -6‬اســتدالل فضيلتــه بــأن األصــل أن العــن اململوكة بيد مالكها‬\n     ‫يتعقــب عليــه أن املدعــى عليــه دفــع خــاف ذلــك ولــم يطلــب منــه إثبــات‬\n     ‫فعلــى فضيلتــه بيــان مســتنده الشــرعي يف هــذا احلكــم واهلل املوفــق‬\n     ‫عليــه أجيــب أصحــاب الفضيلــة حفظهــم اهلل مبــا يلــي أو ًال ‪ :‬إجابــة علــى‬\n     ‫ماذكــر يف أو ًال وسادسـ ًا فــإن أصحــاب الفضيلــة حفظهــم اهلل لــو تأملــوا‬\n     ‫الســاعة التــي وقــع فيهــا احلــادث لوجــدوا أنهــا كانــت يف متــام الســاعة‬\n     ‫الثانيــة عشــرة والنصــف بتاريــخ ‪1433/01/13‬ه ـ وتبليــغ املدعــى عليــه‬\n     ‫كان يف متام الســاعة الواحدة والربع ظهر ًا يف ‪1433/01/13‬هـ حســب‬\n     ‫إفــادة مديــر مــرور منطقــة الريــاض املرفقــة باملعاملــة وليلحــظ أصحــاب‬\n     ‫الفضيلــة أن التبليــغ لــم يكــن بعــد نهايــة الــدوام الرســمي فكيــف علــم‬\n     ‫املدعــى عليــه بالســرقة وهــو يزعــم أنــه يف دوامــه ولــو قبــل هــذا لــكان‬\n     ‫لــكل أحــد أن يفعــل الشــيء ذاتــه ليســلم مــن تبعــات أفعالــه ويزعــم أن‬\n     ‫الســيارة قــد ســرقت ثانيـ ًا ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بنســبة احلــادث‬\n     ‫وقدرهــا مائــة باملائــة ثالث ـ ًا ‪ :‬أمــا اســتمارة الســيارة فقــد جــرى االطــاع‬\n     ‫عليهــا ومطبوعاتهــا مرفقــة باملعاملــة مــن اجلهــة الرســمية رابع ـ ًا ‪ :‬وأمــا‬\n     ‫النســبة املقــررة يف تقريــر املــرور فقــد ســبق أن عرضتهــا علــى املدعــى‬\n     ‫عليــه واعتــرض عليهــا وأمــا مــا ذكــر مــن البصمــة فمحلــه قــد فــات ألن‬\n     ‫الواجــب هــو رفعهــا خــال املــدة العلميــة لهــا وهــي ثمانيــة وأربعــون ســاعة‬\n     ‫لــذا فإنــي علــى مــا حكمــت بــه ورفعــت اجللســة يف متــام الســاعة الواحــدة‬\n     ‫والنصــف وبــاهلل التوفيــق ؛ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                     ‫إلــه وصحبــة وســلم ‪ .‬حــرر يف ‪1434/03/11‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n     ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n\n\n‫‪51‬‬\n\f‫الــواردة مــن فضيلــة رئيس احملكمة العامة بالرياض برقم‪34/749270‬‬\n‫وتاريــخ ‪1434/6/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪ ...‬وتاريخ‪1433/8/4‬ه ـ اخلــاص‬\n‫بدعــوى ‪ ...‬ضــد ‪ ...‬يف قضيــة حــادث مــروري علــى النحــو املوضــح بالصــك‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه ‪ .‬حيــث ســبق‬\n‫دراســة الصــك وصــورة ضبطــه والئحــة وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي واحلقــه بالصــك وصــورة ضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪34200889‬وتاريــخ ‪1434/4/29‬ه ـ لــم يظهــر لألكثريــة‬\n‫مــا يوجــب املالحظــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪52‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":45,"source_page_end":52,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"29d183bbb9fe99b9fe6defad2c4ea13c14ea133ce3078dd2c5dc7cb1fa040316","normalized_text_hash":"5c403880db6ac00899f991c12c20c8e9eafca4e7617e2bc223beb589ed675af6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p45-33366840"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
